// Shared learning and planning views belong to the character catalogue.
let rosterView='cards',rosterLearningKind='learnedSkills',rosterLearningSkill='all',mapPurpose='all';
const LEARN_KINDS={learnedSkills:'技能等级特技',combatArts:'战技',magic:'法术'};
function rosterViewTabs(){return `<nav class="roster-views" aria-label="角色图鉴展示方式">${[['cards','角色卡片'],['data','成长档案'],['plans','队伍规划'],['compare','角色对比'],['gifts','赠礼指南']].map(([k,n])=>`<a href="#characters/${k}" ${rosterView===k?'aria-current="page"':''}>${n}${k==='plans'?`<span>${preferences.size}</span>`:''}</a>`).join('')}</nav>`}
function rosterContent(list){if(!list.length)return '<p class="roster-empty" role="status">没有符合当前筛选的角色，请调整筛选或搜索词。</p>';if(rosterView==='data')return characterDataTable(list);return growthLegend()+`<div class="char-grid">${list.map(card).join('')}</div>`}
function rosterPreferences(){const chosen=DB.characters.filter(c=>searchText(c).includes(query.toLowerCase()));return `<section class="roster-preferences"><div class="preference-summary"><div><strong>${preferences.size}</strong><span>名偏好角色</span></div><div><button data-pref-action="clear">清空偏好</button><button data-pref-action="restore">恢复最初偏好</button>${preferenceUndo?'<button data-pref-action="undo">撤销上次重置</button>':''}<a class="button-link" href="#overview">查看路线攻略 ↗</a><a class="button-link" href="#calculator">自定义养成 ↗</a></div></div>${filterDeck(toolbar('搜索角色，包括别名…',searchCount(chosen.length,DB.characters.length,'名角色')))}<div class="preference-grid">${chosen.map(c=>`<article class="preference-item ${isPreferred(c)?'chosen':''}"><button class="preference-person" data-char="${c.id}">${portrait(c)}<span><b>${esc(c.cn)}</b><small data-skill-images="off">${c.rating} · ${esc(c.role)}</small></span></button>${preferenceButton(c,true)}</article>`).join('')}</div>${preferencePlan()}</section>`}
function learningAbility(c,s,kind){const type=kind==='combatArts'?'战技':kind==='magic'?'法术':'特技';return CATALOG.abilities.find(a=>a.type===type&&a.name===s.name&&a.acquisition.some(x=>x.characterId===c.id))||CATALOG.abilities.find(a=>a.type===type&&a.name===s.name)}
function learnableToken(c,s,kind){const a=learningAbility(c,s,kind),rank=s.level?'Lv.'+s.level:s.rank||s.condition||'—';return `<span class="learning-token">${a?`<button data-reference-type="ability" data-reference-id="${escapeAttr(a.id)}">${esc(s.name)}</button>`:`<span tabindex="0" title="${escapeAttr(s.description||'')}">${esc(s.name)}</span>`}<small>${esc(rank)}</small></span>`}
function learningOrder(s){if(s.level)return Number(s.level);const ranks=['初期','D','D+','C','C+','B','B+','A','A+','S','S+'];const n=ranks.indexOf(s.rank);return n<0?999:n}

// Strengthened skills replace their own earlier version; +1 and ++ are suffixes too.
function skillUpgradeKey(name){return String(name).normalize('NFKC').trim().replace(/\++\d*$/,'')}
function skillUpgradeTier(name){const suffix=String(name).normalize('NFKC').trim().match(/(\++)(\d*)$/);return suffix?Number(suffix[2]||suffix[1].length):0}
function strongestSkillVersions(rows){const best=new Map();for(const a of rows){const key=skillUpgradeKey(a.name),old=best.get(key);if(!old||skillUpgradeTier(a.name)>skillUpgradeTier(old.name))best.set(key,a)}return [...best.values()]}

// Independent contexts: route guide, character dossier and map explorer.
let renderingGuide=false,openPanels=new Set(),detailRoutes={},detailStrategies={},mapArea='all',characterMapQuery='',characterMapArea='all',gearQuantities={},gearSources={},disclosureSeq=0,MAP_EXTRAS=null,mapExtrasLoading=false;
function guidePage(){const page=location.hash.slice(1).split('/')[0];return !page?'home':page}
function viewHTML(h){if(activeCharacter&&h.includes('detail-hero')){const c=DB.characters.find(c=>c.id===activeCharacter);if(c&&!showCharacterMap(c))h=h.replace(/<button([^>]*data-character-(?:gear|material)[^>]*)>([\s\S]*?)<\/button>/g,(_,attr,body)=>attr.includes('gear-location')?'':`<span>${body}</span>`)}return decorateSkillHTML(zhHTML(h)).replace(/<p[^>]*>\s*(?:[·；、]\s*)*<\/p>/g,'').replace(/<details([^>]*)>\s*<summary>([\s\S]*?)<\/summary>/g,(_,attr,title)=>{const id='disclosure-'+(++disclosureSeq),key=attr.match(/data-disclosure-key="([^"]+)"/)?.[1]||title.replace(/<[^>]*>/g,'').trim(),open=/\bopen\b/.test(attr)||openPanels.has(key);return `<section class="disclosure ${esc(attr.match(/class="([^"]+)"/)?.[1]||'')} ${open?'expanded':''}"><button class="disclosure-heading" data-disclosure data-panel-key="${esc(key)}" aria-expanded="${open}" aria-controls="${id}"><span>${title}</span><i aria-hidden="true"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></i></button><div class="disclosure-body" id="${id}" ${open?'':'hidden'}>`}).replace(/<\/details>/g,'</div></section>')}
function available(){return true}
function dataRoute(c){return detailRoutes[c.id]||'summary'}
function routeContext(c){if(typeof collectionComputing!=='undefined'&&collectionComputing)return route==='救世篇'?'summary':route;return activeCharacter===c.id&&!renderingGuide?dataRoute(c):guidePage()==='overview'?route:'summary'}
function loadingBlock(text,{rows=3,compact=false}={}){return `<div class="loading-block ${compact?'compact':''}" role="status" aria-live="polite"><svg class="loading-weave" viewBox="0 0 120 16" width="120" height="16" fill="none" aria-hidden="true"><path class="w1" pathLength="1" d="M0 8C10 1 20 1 30 8s20 7 30 0 20-7 30 0 20 7 30 0"/><path class="w2" pathLength="1" d="M0 8C10 15 20 15 30 8s20-7 30 0 20 7 30 0 20-7 30 0"/></svg><span>${esc(text)}</span>${compact?'':`<div class="loading-skeleton" aria-hidden="true">${Array.from({length:rows},(_, i)=>`<i style="--w:${[92,78,64,85,70][i%5]}%;--d:${i*120}ms"></i>`).join('')}</div>`}</div>`}
const SEARCH_ICON='<svg class="search-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>';
function searchField({attrs='id="search"',value=query,placeholder='搜索…',label='搜索当前目录',kbd=true}={}){return `<label class="search ${value?'has-value':''}">${SEARCH_ICON}<input ${attrs} type="search" value="${esc(value)}" placeholder="${esc(placeholder)}" aria-label="${esc(label)}" autocomplete="off" enterkeyhint="search">${value?'<button type="button" class="search-clear" data-search-clear aria-label="清空搜索"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button>':kbd?'<kbd class="search-kbd" aria-hidden="true">/</kbd>':''}</label>`}
function searchCount(n,total,unit){return n==null?'':`<span class="search-count" role="status" aria-live="polite"><b>${n}</b>${total!=null&&total!==n?` / ${total}`:''} ${esc(unit||'项')}</span>`}
function toolbar(placeholder='搜索角色、职业或技能…',count=''){return `<div class="toolbar search-bar">${searchField({placeholder})}${count}</div>`}
// 资料页统一的检索面板：搜索栏在上，其下为「标签 + 胶囊筛选／下拉」行。
function filterDeck(search,rows=[]){const body=rows.filter(r=>r&&r[1]).map(([label,html,cls=''])=>`<div class="fdeck-row ${cls}"><div class="fdeck-label">${label}</div><div class="fdeck-ctrl">${html}</div></div>`).join('');return `<div class="fdeck${body?'':' fdeck-solo'}">${search}${body?`<div class="fdeck-rows">${body}</div>`:''}</div>`}
function joinTextFor(c,r){const j=c.joinDetails.find(j=>j.route===r+'編'&&j.method!=='対象外'),v=c.routes[r]||{};if(!j&&!c.routes[r])return '不可招募';return [j?.method==='ストーリー'?'剧情入队':'招募',j?.part,j?.chapter?'初见 '+j.chapter:'',joinDateText(j),j?.method==='ストーリー'?'':(j?.renown||v.renown)?'声望 '+(j?.renown||v.renown):'',j?.method==='ストーリー'?'':(j?.support||v.support)?'支援 '+(j?.support||v.support):''].filter(Boolean).join(' · ')}
function canRide(c){return c.canRide}
function strengthRoute(c){const rs=Object.keys(routes).filter(r=>r!=='救世篇'&&firstPartHere(c,r));return rs.sort((a,b)=>routeCost(c,a)-routeCost(c,b))[0]}
function finalBuild(c){return CATALOG.planning[c.id].final}
function profileBuild(c,r){return CATALOG.planning[c.id].routes[r]?.build||CATALOG.planning[c.id].summary}
function profileName(c,r=routeContext(c)){return r==='summary'?'终局整合':trainingProfiles(c)[r]?.label||'后期即战力'}
function card(c){const b=buildPlan(c);return `<article class="char-card ${isPreferred(c)?'preferred-card':''}" data-char="${c.id}" aria-label="${c.cn}培养方案"><div class="char-top"><div class="char-person">${portrait(c)}<span class="char-person-copy"><span class="char-name-row"><button class="char-name text-button" data-char="${c.id}" aria-label="查看${c.cn}培养详情">${c.cn}</button>${preferenceButton(c,true)}</span><small data-skill-images="off">${esc(c.role)}</small></span></div>${ratingBadge(c,true,true)}</div>${joinBadges(c)}<div class="rating-spacer" aria-hidden="true"></div>${cardSkillGrowth(c)}${heat(c.growth)}${cardCareer(c,b)}<div class="card-spacer" aria-hidden="true"></div><section class="card-loadout card-gear-inline">${cardEquipment(c)}</section></article>`}
let primaryRouteFilter='all',familySet=new Set(),primaryRouteSet=new Set(),tierSet=new Set(),lastPrimaryScalar='all',lastFamilyScalar='all',lastTierScalar='all';
function syncMultiSet(set,scalar,last){if(scalar!==last){set.clear();if(scalar!=='all')set.add(scalar);}return scalar;}
function matchesPrimaryRouteFor(c,r){return r==='all'||(r==='third'?!c.firstPart:isPrimaryHere(c,r))}
function matchesPrimaryRoute(c){lastPrimaryScalar=syncMultiSet(primaryRouteSet,primaryRouteFilter,lastPrimaryScalar);if(!primaryRouteSet.size)return true;for(const r of primaryRouteSet)if(matchesPrimaryRouteFor(c,r))return true;return false}
function matchesFamilyFilter(c){lastFamilyScalar=syncMultiSet(familySet,family,lastFamilyScalar);const matchOne=f=>f==='all'||(f==='preferred'?isPreferred(c):c.family===f);if(!familySet.size)return true;for(const f of familySet)if(matchOne(f))return true;return false}
function matchesTierFilter(c){lastTierScalar=syncMultiSet(tierSet,tier,lastTierScalar);if(!tierSet.size)return true;return tierSet.has(c.rating)}
function toggleMultiFilter(set,val){if(val==='all'){set.clear();return 'all'}if(set.has(val)){set.delete(val);if(!set.size)return 'all';return [...set].at(-1)}set.add(val);return val}
function ratingBadge(value,interactive=false,art=false){
 const tier=typeof value==='string'?value:value.rating,name=typeof value==='string'?'':value.cn+'：';
 const label=name+'综合评级 '+tier+(interactive?'，查看评级说明':''),body=art?`<span class="rating-letter" aria-hidden="true">${esc(tier[0])}</span>${tier.length>1?`<span class="rating-modifier" aria-hidden="true">${esc(tier.slice(1))}</span>`:''}`:esc(tier),classes='rating rating-'+esc(tier)+(art?' rating-art':'');
 return interactive?`<button class="${classes}" data-ratings aria-haspopup="dialog" aria-label="${esc(label)}" title="${esc(label)}">${body}</button>`:`<span class="${classes}" role="img" aria-label="${esc(label)}">${body}</span>`;
}
function statPanel(stats,keys=Object.keys(statNames),digits=null){return `<div class="entry-stat-grid">${keys.map(k=>{const v=stats?.[k];return `<div><small>${statNames[k]}</small><b>${v==null?'—':digits===null?v:Number(v).toFixed(digits)}</b></div>`;}).join('')}</div>`;}
function initialDataPanel(c){const marks=Array.isArray(c.bloodMarks)?c.bloodMarks:[];return `<section class="initial-data"><h2>参考基础与血印</h2><div class="entry-meta"><span>参考等级 <b>${esc(c.baseLevel||'未记录')}</b></span><span>初始职业 <b>${esc(c.startClass||'未记录')}</b></span></div>${statPanel(c.baseStats)}<p class="entry-scope-note">所示等级参考快照；实际入队面板随招募章节与等级变化。</p><div class="bloodmark-grid">${marks.length?marks.map(m=>`<article><b>${esc(typeof m==='string'?m:m.name)}</b><p>${esc(typeof m==='string'?'效果未单独记录':m.text||'隐藏条目，效果与开放条件待核实')}</p>${typeof m==='object'&&m.unlock?`<small>${esc(m.unlock)}</small>`:''}</article>`).join(''):'<p class="muted">资料未列出血印。</p>'}</div></section>`}
function previewCharacterGrowth(classTitle){if(!activeCharacter)return;selectedClasses[activeCharacter]=classTitle;openCharacter(activeCharacter,true);const cl=classBy(classTitle),btn=cl&&document.querySelector(`#characterPage .path-class[data-reference-id="${cl.id}"]`);if(btn){if(typeof selectDossierNode==='function')selectDossierNode(btn);btn.focus({preventScroll:true})}}
function affinityStatusIcon(state){return `<svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">${state==='good'?'<path d="M6 2v8M2 6h8"/>':state==='bad'?'<path d="M2 6h8"/>':'<circle cx="6" cy="6" r="2" fill="currentColor" stroke="none"/>'}</svg>`}
function dossierControls(e){const preview=e.target.closest('[data-apply-class]');if(preview){previewCharacterGrowth(preview.dataset.applyClass);return true}return false}
function preferenceEntry(){return `<div class="roster-preference-entry"><span><b>${preferences.size}</b> 名偏好角色 · 影响路线阵容与收集计划</span><a class="button-link" href="#characters/plans">我的培养 <span aria-hidden="true">↗</span></a></div>`}
function characters(){
 if(rosterView==='gifts')return title('角色图鉴','全角色图鉴','')+rosterViewTabs()+giftsPage().replace(/^<div class="page-title">[\s\S]*?<\/div>/,'');
 if(rosterView==='compare')return title('角色图鉴','全角色图鉴','')+rosterViewTabs()+comparePage().replace(/^<div class="page-title">[\s\S]*?<\/div>/,'');
 if(rosterView==='plans')return title('角色图鉴','全角色图鉴','')+rosterViewTabs()+rosterPreferences();
 const list=DB.characters.filter(c=>matchesPrimaryRoute(c)&&matchesTierFilter(c)&&matchesFamilyFilter(c)&&searchText(c).includes(query.toLowerCase()));
 const filters={all:'全部',preferred:'我的偏好',dancer:'再行动',sword:'剑系',axe:'斧系',fist:'拳系',bow:'弓系',magic:'魔法',lance:'枪骑'};
 const primary={all:'全部',...Object.fromEntries(Object.entries(routes).filter(([k])=>k!=='救世篇').map(([k,v])=>[k,v+'篇'])),third:'第三部加入'};
 const famOn=k=>k==='all'?!familySet.size:familySet.has(k);
 const priOn=k=>k==='all'?!primaryRouteSet.size:primaryRouteSet.has(k);
 const tierOn=k=>k==='all'?!tierSet.size:tierSet.has(k);
 const hasMulti=familySet.size>0||primaryRouteSet.size>0||tierSet.size>0;
 return title('全局角色资料','全角色图鉴','')+rosterViewTabs()+`
 ${filterDeck(`<div class="roster-search-row search-bar">${searchField({placeholder:'搜索角色、职业或技能…',label:'搜索角色图鉴'})}${searchCount(list.length,DB.characters.length,'名角色')}${hasMulti?'<button type="button" class="text-button fdeck-reset" data-roster-reset>重置筛选 ↺</button>':''}</div>`,[
 ['职业方向',`<div class="segments" aria-label="职业方向（支持多选）">${Object.entries(filters).map(([k,v])=>`<button data-family="${k}" class="${famOn(k)?'active':''}" aria-pressed="${famOn(k)}">${v}</button>`).join('')}</div>`],
 ['主养路线',`<div class="segments" aria-label="主养路线（支持多选）">${Object.entries(primary).map(([k,v])=>`<button data-primary-route="${k}" class="${priOn(k)?'active':''}" aria-pressed="${priOn(k)}">${v}</button>`).join('')}</div>`],
 [`评级<button class="rating-help" data-ratings aria-label="评级说明" title="评级说明"><span aria-hidden="true">?</span></button>`,`<div class="segments tier-filters" aria-label="评级（支持多选）">${['all',...RATING_TIERS].map(t=>`<button data-tier="${t}" class="${tierOn(t)?'active':''}" aria-pressed="${tierOn(t)}">${t==='all'?'全部':`<i class="tier-dot rating-${t}" aria-hidden="true"></i>${t}`}</button>`).join('')}</div>`]])}
 ${rosterContent(list)}`;
}
function stageClass(name,label,c,context={}){const cl=classBy(name);if(!cl)return `<div class="stage-option ${label==='主选'?'stage-primary':'stage-optional'}"><b>${esc(name)}</b><p>特殊职业资格待核对</p></div>`;return `<div class="stage-option ${label==='主选'?'stage-primary':'stage-optional'}"><div class="stage-option-head"><span class="stage-label">${label}</span><b>${cl.cn}</b><button class="text-button" data-apply-class="${esc(cl.title)}">属性期望</button></div><div class="requirement-pills">${tag(requirement(cl),'key')}${tag('声望 '+(cl.col_32||'特殊'))}${tag('移动 '+(cl.col_34||'—'))}${tag('战技槽 '+(3+(ART_SLOT_BONUSES[cl.cn]||0)),'key')}${tag('特技槽 5')}</div>${signedGrowth(cl)}${careerReasonPanel(cl,c,{...context,label})}${masteryFact(cl)}<details class="class-basics"><summary><span>职业基础</span><small>武器与资格</small></summary><dl class="class-facts"><div><dt>可用技能</dt><dd>${(cl.allowedSkills||[]).map(n=>tag(n)).join('')||'未记录'}</dd></div><div><dt>考试凭证</dt><dd>${esc(cl.col_41||'特殊')}</dd></div><div><dt>解锁前置</dt><dd>${esc(cl.unlock||'无额外事件记录')}</dd></div></dl></details></div>`}
function learningTable(rows,label){if(label==='技能等级特技'){const c=DB.characters.find(c=>c.id===activeCharacter);return `<h3>${label}</h3>${c?skillRankGrid([c],'learnedSkills',rows):''}`} const c=DB.characters.find(x=>x.id===activeCharacter),rec=c?recommendations(c):{arts:[],skills:[]},names=new Set([...rec.arts,...rec.skills,...(rec.magic||[])].map(s=>s.name)),values=s=>[s.range?'射程 '+s.range:'',s.might?'威力 '+s.might:'',s.cost?'消耗 '+s.cost:'',s.uses?'次数 '+s.uses:'',s.weight?'重量 '+s.weight:''].filter(Boolean).join(' · '),hasValues=rows.some(s=>values(s));return `<h3>${label} ${tag(rows.length+'项')}</h3>${rows.length?`<div class="table-wrap"><table><thead><tr><th>技能 / 条件</th><th>效果</th>${hasValues?'<th>数值</th>':''}</tr></thead><tbody>${rows.map(s=>`<tr class="${names.has(s.name)?'recommended-row':''}"><td><b>${esc(s.name)}</b>${names.has(s.name)?tag('推荐','recommend-mark'):''}<small>${esc(s.level?'等级 '+s.level:s.condition||[s.skill,s.rank].filter(Boolean).join(' ')||'条件待核实')}</small></td><td>${emphasis(s.description)}${s.note?`<small>${esc(s.note)}</small>`:''}</td>${hasValues?`<td>${esc(values(s)||'—')}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">暂无已核实条目。</p>'}`}
function mapDOM(sel){return characterOpen()?$('#characterPage').querySelector(sel):$(sel)}
function mapTabs(area,character=false){return `<div class="map-area-tabs segments">${Object.entries({all:'全部地图',...routes}).map(([r,n])=>`<button ${character?'data-character-map-area':'data-map-area'}="${r}" class="${area===r?'active':''}">${n}</button>`).join('')}</div>`}
function materialQueryVariants(q){const aliases=CATALOG.materialAliases||{},key=aliases[q]||q;return [...new Set([q,key,...Object.entries(aliases).filter(([,v])=>v===key).map(([k])=>k)])]}
function mapMatches(p,q){return !q||materialQueryVariants(q).some(term=>`${p.name} ${p.info} ${p.type}`.includes(term))}
function mapMarkup(list,embedded=false){return `<div class="map-layout ${embedded?'embedded-map':''}"><div class="map-viewport" tabindex="0" aria-label="地图：双指缩放、单指拖动，键盘加减号缩放"><div class="map-canvas"><img class="world-map" src="world-map.webp" alt="中文世界地图" decoding="async" draggable="false"><div class="map-tiles"></div><div class="map-pins">${list.map(p=>`<button class="pin ${['蔬菜','鱼','矿石','道具'].includes(p.type)?'gather-pin':'shop-pin'}" style="left:${p.x}%;top:${p.y}%" data-pin="${p.id}" title="${esc(p.name+' · '+p.type)}" aria-label="${esc(p.name+' · '+p.type)}">${embedded&&list.length<70||query||['据点','小据点','神殿','驿站'].includes(p.type)?`<span class="pin-label ${query?'searched-label':''}">${esc(p.name)}</span>`:''}</button>`).join('')}</div></div></div><aside class="map-results"><h3>${list.length}个相关点位</h3>${list.map(p=>`<button class="map-result" data-pin="${p.id}"><b>${esc(p.name)}</b><small>${routes[p.area]||p.area} · ${esc(p.type)}</small><p>${esc(p.info)}</p></button>`).join('')||'<p>没有已收录点位；地点文字说明仍见装备来源。</p>'}</aside></div>`}
function uniquePins(list){const seen=new Set();return list.filter(p=>{const key=p.name+Math.round(p.x)+':'+Math.round(p.y);if(seen.has(key))return false;seen.add(key);return true})}
