function actionChips(c,compact=false){const r=recommendations(c),chip=(a,type)=>`<span class="action-chip ${type}-chip" title="${esc(a.why||a.description||'按习得条件使用')}">${esc(a.name)}${compact?'':`<em>${esc(a.rank||(a.level?'Lv'+a.level:'条件'))}</em>`}</span>`,row=(name,items,type)=>`<div class="${compact?'loadout-row':'action-row'}"><small>${name}</small><div class="chip-list" ${compact?'aria-label="'+name+'推荐"':''}>${items.length?items.map(a=>chip(a,type)).join(''):'<span class="muted">普通攻击、恢复或法术为主</span>'}</div></div>`;return `<div class="action-chips ${compact?'compact-actions':''}">${row(compact?'战技':`战技 ${r.arts.length}/${r.slots}`,r.arts,'art')}${r.magic.length?row('法术',r.magic,'magic'):''}${row(compact?'特技':`特技 ${r.skills.length}/5`,r.skills,'skill')}</div>`}
function qualificationTargets(c){if(c.canUseArenaTraining===false)return [];const b=buildPlan(c),good=c.good.split(':').map(skillName),goal=new Map();for(const n of [...b.mid.slice(0,1),...b.upper.slice(0,1)]){const cl=classBy(n);if(!cl)continue;for(const [s,rank] of [...cl.must,...(cl.any.length?[cl.any.find(([s])=>b.focus.includes(s))||cl.any.find(([s])=>good.includes(s))||cl.any[0]]:[])]){const current=goal.get(s);if(!current||rankValue(rank)>rankValue(current.rank))goal.set(s,{rank,cl:cl.cn})}}return [...goal].map(([skill,v])=>({skill,...v}))}
