function petLocationMap(p){if(!mapLoaded){loadMap();return loadingBlock('正在载入捕获地点地图…',{compact:true})}const pins=p.places.map(place=>PINS.find(pin=>pin.area==='カイ'&&pin.name===place)).filter(Boolean);if(!pins.length)return '';const xs=pins.map(pin=>pin.x*33.28),ys=pins.map(pin=>pin.y*25.6),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,w=Math.max(700,Math.max(...xs)-Math.min(...xs)+300,(Math.max(...ys)-Math.min(...ys)+260)*16/9),h=w*9/16;return `<figure class="pet-location-map"><svg viewBox="${cx-w/2} ${cy-h/2} ${w} ${h}" role="img" aria-label="${esc(p.name)}捕获地点：${esc(p.places.join('、'))}"><image href="world-map.webp" x="0" y="0" width="3328" height="2560"/>${pins.map((pin,i)=>`<g transform="translate(${xs[i]} ${ys[i]})"><circle r="13" fill="#675276" stroke="#fffefa" stroke-width="4"/><rect x="-85" y="-53" width="170" height="31" rx="7" fill="#fffefaf2"/><text x="0" y="-31" text-anchor="middle" fill="#302e39" font-size="21" font-weight="600">${esc(pin.name)}</text></g>`).join('')}</svg></figure>`}
function petCard(p){return `<article class="pet-card"><h3>${p.name} ${tag(p.category)}</h3><div class="pet-facts"><span><small>食材 / 口味</small><b>${p.food} · ${p.taste}</b></span></div><section class="pet-location-block"><small>捕获地点</small><b>${p.places.join(' / ')}</b>${petLocationMap(p)}</section><p class="muted">${esc(p.unlock)}</p><div class="pet-growth">${Object.entries(p.growth).filter(([k,v])=>v).map(([k,v])=>tag(statNames[k]+' ＋'+v,'green')).join('')}</div><small>以上为友好5、兼容职业骑乘升级时的成长修正</small><details><summary>骑乘技能与适配职业 ${tag(p.skills.length+'类个体')}</summary>${p.skills.map(s=>`<p><b>${s.label}</b> · ${s.effect}</p>`).join('')}<p>${p.compatibleClasses.join(' / ')}</p>${link(p.source,'动物数据')}</details></article>`}
function kaiCharacter(c){const rec=PET_GUIDE.recommendations.find(r=>r.characterId===c.id);if(!rec)return '';const pets=rec.primary.pets.map(id=>PET_GUIDE.pets.find(p=>p.id===id)).filter(Boolean);return `<section class="character-pets"><h2>凯伊线骑宠方案</h2><p><b>${rec.primary.class}</b> · ${esc(rec.primary.goal)}</p><p>${esc(rec.primary.reason)}</p>${note(esc(rec.timing))}<div class="pet-grid">${pets.map(petCard).join('')}</div><p class="muted">友好由该角色本人培养；相同种类不同个体技能可能不同。天马只适配天翼系，驭龙职业须另配龙类骑宠。</p></section>`}
