function equipmentEntries(cs,allOptions=false){const entries=new Map();for(const c of cs){const b=buildPlan(c),focus=b.focus;let ids=allOptions?c.gearIds:focus.includes('黑魔')?['magic_staff',...(focus.includes('剑')?['thunder']:[])]:focus.includes('白魔')?['heal']:focus.includes('格斗')?['daminafist']:focus.includes('弓')?['damina_bow','longbow']:focus.includes('枪')?['aurora_lance']:focus.includes('斧')?['daminaaxe']:['daminasword'];if(c.id==='c7')ids=['clean','carla','swift'];for(const id of ids){const e=EQUIPMENT.find(e=>e.id===id);if(!e)continue;if(!entries.has(id))entries.set(id,{e,users:[]});entries.get(id).users.push(c)}}return [...entries.values()]}
function selectedGear(entries,scope){return entries.map(({e,users})=>{const key=scope+':'+e.id,chosen=gearSources[key]??gearSources[zh(key)];const idx=Number.isInteger(chosen)&&chosen>=0&&chosen<e.sourcesList.length?chosen:Math.max(0,e.sourcesList.findIndex(s=>s.kind.includes('购买')));const source=e.sourcesList[idx]||e.sourcesList[0],buy=/购买/.test(source?.kind||''),exchange=/兑换/.test(source?.kind||source?.text||''),qty=['carla','swift','giant','clean'].includes(e.id)?1:users.length,owned=weaponInventory[e.id]||0,remaining=Math.max(0,qty-owned);const mats=materialsForSource(e,source);const stock=Number(source?.text.match(/库存\s*(\d+)/)?.[1]||0);return {e,users,scope,key,idx,source,buy,exchange,qty,owned,remaining,mats,stock}})}
function materialTotals(items){const totals=new Map();for(const item of items){const count=item.remaining??item.qty;if(!count)continue;for(const m of item.mats){const id=m[0];if(!totals.has(id))totals.set(id,{m,qty:0,uses:[]});const t=totals.get(id);t.qty+=Number(m[2])*count;t.uses.push(item.e.name+' × '+count)}}return [...totals.values()]}
