let equipmentSort='';
function equipmentStatValue(e,label){const v=equipmentMetrics(e).find(([,l])=>l===label)?.[2];if(v===undefined)return null;const n=parseFloat(String(v).replace('−','-'));return Number.isFinite(n)?n:null}
function equipment(){const types=['all',...['剑','枪','斧','弓','手甲','盾','杖','饰品','面具'].filter(t=>EQUIPMENT.some(e=>e.type===t))],sorts=[['','默认顺序'],['威力','威力从高到低'],['命中','命中从高到低'],['必杀','必杀从高到低'],['重量','重量从轻到重']];const forNames=e=>(e.recommendedBy||[]).map(r=>DB.characters.find(c=>c.id===r.id)?.cn||'').join(' ');let list=EQUIPMENT.filter(e=>(equipmentType==='all'||e.type===equipmentType)&&(!equipmentFor||(e.recommendedBy||[]).some(r=>r.id===equipmentFor))&&[query,query.replaceAll('拳套','手甲')].some(q=>JSON.stringify(e).includes(q)||forNames(e).includes(q)));if(equipmentSort){const asc=equipmentSort==='重量';list=[...list].sort((a,b)=>{const x=equipmentStatValue(a,equipmentSort),y=equipmentStatValue(b,equipmentSort);if(x===null&&y===null)return 0;if(x===null)return 1;if(y===null)return -1;return asc?x-y:y-x})}return title('全局装备资料','装备图鉴','')+'<a class="button-link inventory-entry" href="#collection" data-open-inventory>管理武器与材料库存 ↗</a>'+filterDeck(toolbar('搜索武器、材料、地点…',searchCount(list.length,EQUIPMENT.length,'件')),[['类型',`<div class="segments equipment-types">${types.map(t=>`<button data-equipment-type="${esc(t)}" class="${equipmentType===t?'active':''}">${t==='all'?'全部':esc(t)} <span>${t==='all'?EQUIPMENT.length:EQUIPMENT.filter(e=>e.type===t).length}</span></button>`).join('')}</div>`],['筛选',`${peopleFilter('equipment',equipmentFor,EQUIPMENT)}<label class="class-sort">排序<select data-equipment-sort aria-label="装备排序">${sorts.map(([v,l])=>`<option value="${v}" ${equipmentSort===v?'selected':''}>${l}</option>`).join('')}</select></label>`,'fdeck-selects']])+`${equipmentViews(`<div class="equipment-library equipment-ledger"><div class="equipment-ledger-head" aria-hidden="true"><span>装备</span><span>性能</span><span>效果与获取</span><span>推荐角色</span></div>${list.map(equipmentCard).join('')||'<p class="muted">没有匹配装备。</p>'}</div>`,list)}`}

let recruitScope='レダ',recruitFilter='all';
function recruitRecords(){return DB.characters.flatMap(c=>c.joinDetails.filter(j=>j.method!=='対象外'&&(recruitScope==='common'?j.route==='共通':j.route===recruitScope+'編'&&j.part==='第一部')).map(j=>({c,j,story:j.method==='ストーリー',quests:recruitScope==='common'?[]:timing(c,recruitScope).quest})));}
function recruit(){const all=recruitRecords(),selected=all.filter(({c,story,quests})=>searchText(c).includes(query.toLowerCase())&&(recruitFilter==='all'||recruitFilter==='story'&&story||recruitFilter==='scout'&&!story||recruitFilter==='quest'&&(quests.length||/外传|任务/.test(JSON.stringify(c.joinDetails)))||recruitFilter==='preferred'&&isPreferred(c))),groups=new Map();for(const item of selected){const key=recruitScope==='common'?item.j.part||'共通记录':item.story?'剧情入队':item.j.renown?'声望 '+item.j.renown:'特殊条件';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);}const order=([...groups.keys()]).sort((a,b)=>{if(a==='剧情入队')return -1;if(b==='剧情入队')return 1;return (parseInt(a.match(/\d+/)?.[0]||'999')-parseInt(b.match(/\d+/)?.[0]||'999'));});return title('全局招募资料','招募与声望','')+`<div class="route-tabs recruit-tabs" role="tablist" aria-label="招募路线">${Object.entries({...Object.fromEntries(Object.entries(routes).filter(([key])=>key!=='救世篇')),common:'共通 / 后期'}).map(([key,label])=>`<button role="tab" data-recruit-scope="${escapeAttr(key)}" aria-selected="${recruitScope===key}" class="${recruitScope===key?'active':''}">${label}${key==='common'?'':'篇'}</button>`).join('')}</div><div class="recruit-dashboard"><article><strong>${new Set(all.map(x=>x.c.id)).size}</strong><span>可入队角色</span></article><article><strong>${all.filter(x=>x.story).length}</strong><span>剧情入队</span></article><article><strong>${all.filter(x=>!x.story).length}</strong><span>条件招募</span></article><article><strong>${all.filter(x=>isPreferred(x.c)).length}</strong><span>我的偏好</span></article></div>`+filterDeck(toolbar('搜索角色、地点或前置条件…',searchCount(selected.length,all.length,'名角色')),[['入队方式',`<div class="segments recruit-filters">${Object.entries({all:'全部',story:'剧情入队',scout:'条件招募',quest:'任务相关',preferred:'我的偏好'}).map(([key,label])=>`<button data-recruit-filter="${key}" class="${recruitFilter===key?'active':''}">${label}</button>`).join('')}</div>`]])+`<div class="recruit-timeline">${order.map(key=>{const list=groups.get(key).sort((a,b)=>Number(a.j.chapter.match(/\d+/)?.[0]||0)-Number(b.j.chapter.match(/\d+/)?.[0]||0));return `<section class="recruit-group"><div class="recruit-group-heading"><span class="recruit-group-marker">${key.startsWith('声望 ')?key.replace('声望 ',''):key==='剧情入队'?'✦':'◇'}</span><h2>${esc(key)}</h2>${tag(list.length+'人')}</div><div class="table-wrap"><table class="recruit-table"><thead><tr><th>角色 / 定位</th><th>初次出现</th><th>入队条件</th><th>地点与前置</th></tr></thead><tbody>${list.map(({c,j,story,quests})=>`<tr class="${isPreferred(c)?'recruit-preferred':''}"><td>${tableCharacter(c,{recruit:true,extra:c.birthday?` · 生日 ${esc(c.birthday)}`:''})}</td><td><b>${esc(j.chapter||j.part||'未单独记录')}</b>${joinDateText(j)?`<small>${esc(joinDateText(j))}</small>`:''}</td><td><div class="recruit-requirements">${story?tag('剧情入队','green'):j.renown?tag('声望 '+j.renown,'key'):tag('特殊条件')}${!story&&j.support?tag('支援 '+j.support):''}${quests.length?tag('任务前置','key'):''}${j.deadline?tag('时限','key'):''}</div>${j.answers?`<small class="recruit-answers">答题：${esc(j.answers)}</small>`:''}${j.deadline?`<small class="recruit-deadline">${esc(j.deadline)}</small>`:''}</td><td>${j.place?`<b class="recruit-place">${esc(j.place)}</b>`:''}${[j.prerequisite,j.note,...quests.map(q=>q.name+' · 第'+q.chapter+'章')].filter(Boolean).map(text=>`<small>${esc(text)}</small>`).join('')||'<small>无额外前置记录</small>'}${!story&&j.negotiate?`<small>交涉：${esc(j.negotiate)}</small>`:''}${j.gift?`<small>礼物：${esc(j.gift.name)}${j.gift.price?`（${j.gift.price}G）`:''}${j.gift.place?` · <button class="text-button" data-goto-map="${escapeAttr(j.gift.place)}">${esc(j.gift.place)}</button>`:''}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}).join('')||'<div class="feature empty-state">没有符合筛选条件的入队记录。</div>'}</div>`;}

function preferencePlan(){const chosen=DB.characters.filter(c=>isPreferred(c)&&Object.keys(CATALOG.planning[c.id].routes).length);return `<h2>跨线互补培养</h2>${crossRoutePolicyPanel()}<p class="muted">单一职责只分配一条主养线；首选较早达标或更需要该能力的路线。拥有独立实战定位才安排多条主养，重装补属性不构成额外主养理由。</p><div class="table-wrap"><table><thead><tr><th>角色 / 最终职责</th>${Object.entries(routes).filter(([r])=>r!=='救世篇').map(([r,n])=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${chosen.map(c=>`<tr><td>${tableCharacter(c,{subtitle:finalBuild(c).end})}</td>${Object.keys(routes).filter(r=>r!=='救世篇').map(r=>{const p=trainingProfiles(c)[r],b=buildPlan(c,r);return `<td>${p?`<b>${p.optional?'补强 · ':''}${p.label}</b><small>${complementStages(c,b)}</small>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`+note('互补目标可减少重复投入，必要资格技能仍可能重复。候补补属性需要招募后在指定职业实际获得升级；未招募自动成长不能指定职业。融合逐项取高，最终仍是一名角色。')}
function heroArt(h,eager=false){const c=DB.characters.find(c=>c.id===h.id),sources=h.artSources||[CATALOG.presentation.artBase+h.slug+'.webp'];return `<img class="hero-art" width="800" height="900" src="${esc(sources[0])}" data-art-secondary="${esc(sources[1]||'')}" data-art-portrait="${esc(c.portraitFile)}" alt="${esc(c.cn)}主角立绘" loading="${eager?'eager':'lazy'}" decoding="async" fetchpriority="${eager?'high':'low'}" onerror="if(this.dataset.artSecondary){this.src=this.dataset.artSecondary;delete this.dataset.artSecondary}else{this.onerror=null;this.src=this.dataset.artPortrait;this.classList.add('art-fallback')}">`}
function routeTabId(r){return 'route-tab-'+(CATALOG.presentation.heroes.find(h=>h.route===r)?.slug||'third')}
function routePicker(){const entries=[...CATALOG.presentation.heroes.map(h=>({r:h.route,c:DB.characters.find(c=>c.id===h.id)})),{r:'救世篇'}];return `<div class="route-hero-picker" role="tablist" aria-label="路线攻略篇章">${entries.map(({r,c})=>`<button role="tab" id="${routeTabId(r)}" data-guide-route="${r}" aria-controls="route-guide-panel" aria-selected="${route===r}" tabindex="${route===r?0:-1}" class="${route===r?'active':''}">${c?portrait(c,true):`<img class="route-group-portrait" src="assets/route-group.svg" alt="四位主角">`}<span class="route-tab-copy"><b>${c?esc(c.cn)+'篇':'第三部'}</b><small>${route===r?'当前攻略':c?'第一部':'同伴合流'}</small></span></button>`).join('')}</div>`}
function selectGuideRoute(r){if(!Object.hasOwn(routes,r))return;route=r;query='';persist();render();$('#'+routeTabId(r))?.focus({preventScroll:true})}
function routeTabKey(e){const tab=e.target.closest?.('[data-guide-route]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const choices=[...CATALOG.presentation.heroes.map(h=>h.route),'救世篇'],i=choices.indexOf(tab.dataset.guideRoute),next=e.key==='Home'?0:e.key==='End'?choices.length-1:(i+(e.key==='ArrowRight'?1:-1)+choices.length)%choices.length;e.preventDefault();selectGuideRoute(choices[next])}
document.addEventListener('keydown',routeTabKey);

function routeCover(r){const h=CATALOG.presentation.heroes.find(h=>h.route===r);if(!h)return `<section class="route-cover reunion-cover" data-route-theme="reunion" data-skill-images="off"><div class="route-cover-fx" aria-hidden="true"><video class="route-cover-video" autoplay muted loop playsinline preload="metadata" poster="assets/anna-live/bg-poster.webp" src="assets/anna-live/bg.webm"></video><canvas class="route-fx-canvas" data-fx-route="reunion"></canvas></div><div class="reunion-art"><svg class="reunion-composite" viewBox="-30 0 1060 520" width="1060" height="520" preserveAspectRatio="xMidYMax meet" role="img" aria-label="蕾达、凯伊、迪托利希与赛奥朵拉四人合流"><defs><filter id="reunion-depth" x="-15%" y="-15%" width="130%" height="140%"><feDropShadow dx="-8" dy="14" stdDeviation="7" flood-color="#352b27" flood-opacity=".22"/></filter></defs>${CATALOG.presentation.reunionComposition.map(frame=>{const h=CATALOG.presentation.heroes.find(h=>h.id===frame.id),height=frame.height,c=DB.characters.find(c=>c.id===h.id);return `<image class="reunion-${frame.layer}" filter="${frame.layer==='front'?'url(#reunion-depth)':'none'}" x="${frame.x}" y="${frame.y}" width="${height*8/9}" height="${height}" preserveAspectRatio="xMidYMax meet" href="${esc(h.artSources[0])}" data-secondary="${esc(h.artSources[1])}" data-portrait="${esc(c.portraitFile)}" onerror="if(this.dataset.secondary){this.setAttribute('href',this.dataset.secondary);delete this.dataset.secondary}else{this.onerror=null;this.setAttribute('href',this.dataset.portrait)}"/>`}).join('')}</svg></div><div class="route-cover-copy"><h2>四条命运，同赴终局。</h2><div class="cover-tags">${['成长融合','技能整合','终局分队'].map(t=>tag(t)).join('')}</div></div>${routePicker()}</section>`;const c=DB.characters.find(c=>c.id===h.id);return `<section class="route-cover route-theme-${esc(h.slug)}" data-route-theme="${esc(h.slug)}" data-skill-images="off"><div class="route-cover-fx" aria-hidden="true"><video class="route-cover-video" autoplay muted loop playsinline preload="metadata" poster="assets/anna-live/bg-poster.webp" src="assets/anna-live/bg.webm"></video><div class="route-scene-reel" aria-hidden="true"><img class="route-scene-frame scene-a" src="assets/heroes/${esc(h.slug)}-scene-01.webp" alt="" loading="lazy" decoding="async"><img class="route-scene-frame scene-b" src="assets/heroes/${esc(h.slug)}-scene-02.webp" alt="" loading="lazy" decoding="async"></div><canvas class="route-fx-canvas" data-fx-route="${esc(h.slug)}"></canvas></div><div class="route-art-panel"><span class="route-art-halo" aria-hidden="true"></span>${heroArt(h,true)}</div><div class="route-cover-copy"><h2>${esc(h.theme)}</h2><div class="cover-tags">${h.tags.map(t=>tag(t)).join('')}</div><button class="cover-character" data-char="${c.id}">认识${esc(c.cn)} <span aria-hidden="true">↗</span></button></div>${routePicker()}</section>`}
function equipmentIcon(e){const type=e.type==='拳套'?'手甲':e.type,icon=CATALOG.presentation.equipmentIcons[type],src=icon?.src||'';return src?`<img class="equipment-game-icon" src="${esc(src)}" alt="${esc(type+'类游戏图标')}" width="24" height="24" loading="lazy" decoding="async" onerror="this.hidden=true">`:''}

function equipmentSourceModel(e,s){const text=s.text||'',explicit=s.kind==='购买'||s.kind==='兑换',matches=Array.isArray(s.materials)?s.materials:e.materials.filter(m=>text.includes(m[0])),exchange=/兑换|交换/.test(text)||s.kind==='兑换'||matches.length>0&&/商会/.test(text),kind=explicit?s.kind:exchange?'兑换':/购买|武器店|金币|\dG/.test(text)?'购买':/宝箱/.test(text)?'宝箱':/奖励|报酬/.test(text)?'奖励':/任务|试炼|委托/.test(text)?'任务':'获取记录',priceMatch=text.match(/([\d,]+)\s*(?:金币|G)(?![a-z])/i),price=s.price??(priceMatch?Number(priceMatch[1].replaceAll(',','')):null),prefix=text.includes('：')?text.split('：')[0]:'',title=s.shop||prefix||s.place||(kind==='兑换'?'商会兑换':kind==='购买'&&/安娜/.test(text)?'安娜秘密商店':kind==='宝箱'?'宝箱获取':kind==='奖励'?'任务奖励':'获取记录'),singleExchange=e.sourcesList.filter(x=>x.kind==='兑换'||/兑换|交换/.test(x.text)).length===1,mats=exchange?(matches.length?matches:singleExchange?e.materials:[]):[];let note=s.condition?[s.place,s.condition].filter(Boolean).join(' · '):text;if(!s.condition&&prefix)note=note.slice(prefix.length+1);if(!s.condition&&priceMatch)note=note.replace(priceMatch[0],'');if(s.recipePending)note+=' · 兑换配方待核实';if(mats.length&&!s.condition){for(const m of mats){const at=note.indexOf(m[0]);if(at>=0){const before=note.slice(0,at),after=note.slice(at+m[0].length).replace(/^\s*[×x]?\s*\d+/,'');note=before+after}}note=note.replace(/^[\s+、；，。]+/,'')}note=note.replace(/^[\s；，。]+|[；，。\s]+$/g,'').replace(/；[；，]/g,'；');return {kind,title,price,note,mats}}
function equipmentSourcesInline(e){return `<section class="equipment-acquisition"><h4>获取途径</h4><ul class="acquisition-list source-dialog-options equipment-detail-options">${e.sourcesList.map(source=>`<li class="acquisition-item source-option-card">${sourceOptionContent(e,source,false)}<div class="source-detail-meta">${equipmentSourceModel(e,source).price!==null?`<span class="acquisition-price">${equipmentSourceModel(e,source).price.toLocaleString('zh-CN')}<small>金币</small></span>`:''}${source.condition?`<span class="source-detail-condition">${esc(source.condition)}</span>`:''}</div></li>`).join('')}</ul></section>`}
function equipmentMetrics(e){const labels={power:'威力',weight:'重量',hit:'命中',range:'射程',durability:'耐久',critical:'必杀',avoid:'回避',curse:'怨咒'},values=new Map();for(const [key,label]of Object.entries(labels))if(e.stats?.[key]!==undefined&&e.stats[key]!==null)values.set(label,String(e.stats[key]));const weapon=['剑','枪','斧','弓','手甲'].includes(e.type),parts=e.effect.split(/[。；]/),text=weapon?parts[0]:parts.filter(t=>/^\s*(?:重量|速度|力量|魔力|防御|魔防|技巧|幸运|魅力|生命|体格|回避|命中|必杀)/.test(t)).map(t=>t.split(/相邻|邻接|受到|攻击时|战斗时|以战技|装备/)[0]).join('；');for(const match of text.matchAll(/(威力|重量|命中|射程|耐久|必杀|力量|魔力|速度|防御|魔防|技巧|幸运|魅力|生命|体格|回避|怨咒)\s*([+−-]?\d+(?:[–—~-]\d+)?)/g))if(!values.has(match[1]))values.set(match[1],match[2]);return [...values].map(([label,value])=>[label+value,label,value])}
function equipmentRecordCount(){return EQUIPMENT.reduce((total,e)=>total+1+(e.variants?.length||0),0)}
function equipmentVariants(e){
 const vHtml=e.variants?.length?`<section class="equipment-variants"><h3>已收录强化形态</h3><div class="table-wrap"><table><thead><tr><th>形态</th><th>威力</th><th>重量</th><th>命中</th><th>射程</th><th>耐久</th><th>必杀</th><th>回避</th><th>资格</th><th>效果</th></tr></thead><tbody>${e.variants.map(v=>`<tr><td><b>${esc(v.name)}</b></td>${['power','weight','hit','range','durability','critical','avoid'].map(k=>`<td>${esc(v.stats[k]??'—')}</td>`).join('')}<td>${esc(v.rank||'未记录')}</td><td>${esc(v.effect||'未记录额外效果')}</td></tr>`).join('')}</tbody></table></div></section>`:'';
 const fHtml=e.forgeSteps?.length?`<section class="equipment-forging"><h3>铁匠铺强化与锻造${e.maxForge?` <span class="tag key">上限 ${esc(e.maxForge)}</span>`:''}</h3>${e.forgeSummary?`<p class="forge-summary-note">满级性能：<b>${esc(e.forgeSummary)}</b></p>`:''}<div class="table-wrap"><table class="forge-steps-table"><thead><tr><th>阶段</th><th>性能变化</th><th>锻造材料</th><th>金币</th></tr></thead><tbody>${e.forgeSteps.map(st=>`<tr><td><b>${esc(st.step)}</b></td><td>${esc(st.change||'—')}</td><td>${(st.materials||[]).map(m=>`<button type="button" class="text-button forge-mat-link" data-forge-mat="${escapeAttr(m.name)}">${esc(m.name)} × ${m.qty}</button>`).join(' + ')||'剧情解锁'}</td><td>${st.gold?st.gold.toLocaleString('zh-CN')+'G':'—'}</td></tr>`).join('')}</tbody></table></div></section>`:'';
 return vHtml+fHtml;
}

const PEOPLE_LABELS={exclusive:'专属',guide:'攻略推荐',rule:'主武器',late:'第三部替换'};
// Avatar stack used by the class and equipment ledgers; extra faces expand downward so the column never widens.
function peopleStack(list,{max=4,empty='—',label=''}={}){const rows=(list||[]).map(r=>({...r,c:DB.characters.find(c=>c.id===r.id)})).filter(r=>r.c);if(!rows.length)return `<div class="people-stack people-empty"><span class="muted">${empty}</span></div>`;const tagOf=r=>r.stage||PEOPLE_LABELS[r.kind]||'',key=r=>['exclusive','guide','终局'].includes(r.kind||r.stage),counts={};for(const r of rows){const t=tagOf(r);counts[t]=(counts[t]||0)+1;}const face=(r,i)=>`<button class="people-face${key(r)?' is-key':''}${i>=max?' people-extra':''}" data-char="${r.c.id}" title="${esc(r.c.cn)} · ${esc(tagOf(r))}" aria-label="${esc(r.c.cn)}（${esc(tagOf(r))}）">${portrait(r.c)}</button>`;return `<div class="people-stack" data-people-stack aria-label="${esc(label)}推荐角色 ${rows.length} 名"><div class="people-faces">${rows.map(face).join('')}${rows.length>max?`<button class="people-more" data-people-more aria-expanded="false" title="展开全部 ${rows.length} 名">+${rows.length-max}</button>`:''}</div><small class="people-summary">${Object.entries(counts).map(([t,n])=>`${esc(t)} ${n}`).join(' · ')}</small></div>`}
// Searchable character picker shared by the recommendation filters and the compare toolbar; trigger matches the adjacent sort select.
const PICKER_CHECK='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
function characterPickerOption(kind,c,selectedId){return `<button type="button" class="character-filter-option" data-character-filter-pick="${kind}" data-character-filter-value="${c.id}" data-character-filter-text="${esc([c.cn,c.name,c.alias,c.role].filter(Boolean).join(' ').toLowerCase())}" role="option" aria-selected="${selectedId===c.id}">${portrait(c)}<span><b>${esc(c.cn)}</b><small data-skill-images="off">${esc(c.role)}</small></span>${selectedId===c.id?PICKER_CHECK:''}</button>`}
function characterPicker({kind,value='',characters,trigger,aria,clearLabel='',groups=null,variant=''}){
 const selected=characters.find(c=>c.id===value),label=selected?.cn||trigger;
 const clear=clearLabel?`<button type="button" class="character-filter-option character-filter-clear" data-character-filter-pick="${kind}" data-character-filter-value="" role="option" aria-selected="${!selected}"><span><b>${esc(clearLabel)}</b></span>${selected?'':PICKER_CHECK}</button>`:'';
 const options=groups?groups.filter(g=>g.items.length).map(g=>`<div class="character-filter-group" role="group" aria-label="${esc(g.label)}"><p aria-hidden="true">${esc(g.label)}</p>${g.items.map(c=>characterPickerOption(kind,c,value)).join('')}</div>`).join(''):characters.map(c=>characterPickerOption(kind,c,value)).join('');
 return `<div class="character-filter${selected?' is-active':''}${variant?' character-filter-'+variant:''}" data-character-filter="${kind}"><button type="button" class="character-filter-toggle" data-character-filter-toggle="${kind}" aria-expanded="false" aria-controls="character-filter-${kind}" aria-label="${esc(aria+(selected?'，当前'+selected.cn:''))}">${selected?portrait(selected):''}<span class="character-filter-label">${esc(label)}</span><svg class="character-filter-chevron" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><section class="character-filter-popover" id="character-filter-${kind}" role="dialog" aria-label="${esc(aria)}" hidden><div class="character-filter-search">${searchField({attrs:`data-character-filter-search="${kind}"`,value:'',placeholder:'搜索姓名或别名…',label:'搜索角色',kbd:false})}</div><div class="character-filter-list" role="listbox" aria-label="${esc(aria)}">${clear}${options}</div><p class="character-filter-empty" role="status" hidden>没有匹配角色，请换个姓名或别名。</p></section></div>`;
}
function peopleFilter(kind,value,items){const ids=new Set(items.flatMap(x=>(x.recommendedBy||[]).map(r=>r.id)));return characterPicker({kind,value,characters:DB.characters.filter(c=>ids.has(c.id)),trigger:'全部角色',clearLabel:'全部角色',aria:'按推荐角色筛选'})}
