function equipmentCard(e){const stats=equipmentMetrics(e),statToken='(?:威力|重量|命中|射程|耐久|必杀|力量|魔力|速度|防御|魔防|技巧|幸运|魅力|生命|体格|回避)\\s*[+−-]?\\d+(?:[–—~-]\\d+)?',description=e.effect.replace(new RegExp('^(?:\\s*'+statToken+'[。 /；，、]*)+'),'').replace(new RegExp('(?:[。；]|\\s/\\s)\\s*(?:'+statToken+'\\s*[ /；，、]*)+。?$'),'').replace(/[；，、\s]+$/,'').trim();const sortKey=equipmentSort,cells=stats.slice(0,6);return `<article class="equipment-row" id="gear-${e.id}" role="button" tabindex="0" data-reference-type="equipment" data-reference-id="${e.id}" aria-haspopup="dialog" aria-label="查看${esc(e.name)}装备详情"><div class="equipment-row-name" data-skill-images="off"><div class="weapon-icon">${equipmentIcon(e)||`<span>${esc(e.type)}</span>`}</div><div><h3>${esc(e.name)}</h3><small>${esc(e.rank)} · ${esc(e.type)} · ${esc(e.phase)}</small></div></div><dl class="equipment-row-stats" data-skill-images="off">${cells.length?cells.map(([,label,value])=>`<div class="${label===sortKey?'sorted ':''}${label==='威力'?'stat-primary':''}"><dt>${label}</dt><dd>${value}</dd></div>`).join(''):'<div class="equipment-row-nostat"><dt>性能</dt><dd>—</dd></div>'}</dl><div class="equipment-row-info"><p class="equipment-row-effect">${esc(description||e.purpose||'按装备基础性能使用。')}</p>${equipmentSourcePreview(e)}</div>${peopleStack(e.recommendedBy,{label:e.name})}</article>`}
document.addEventListener('keydown',e=>{const card=e.target.closest?.('.equipment-preview');if(card&&['Enter',' '].includes(e.key)){e.preventDefault();openReferenceDialog('equipment',card.dataset.referenceId)}const tab=e.target.closest?.('[data-guide-view]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const keys=guideViewOptions().map(([key])=>key),i=keys.indexOf(routeGuideView);routeGuideView=keys[e.key==='Home'?0:e.key==='End'?keys.length-1:(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length];query='';recruitFilter='all';render();document.getElementById('guide-view-'+routeGuideView)?.focus({preventScroll:true})}});

