function guideViewOptions(){const hasCalendar=route!=='救世篇'||ROUTE_EVENTS.some(e=>e.route===route)||(CATALOG.chapterCalendar.mainline[route]||[]).length;return [['plan','培养规划'],...(route==='カイ'?[['pets','捕获与骑兵']]:[]),['recruit','招募与声望'],...(hasCalendar?[['calendar','任务与观战日历']]:[]),['equipment','装备与材料']]}
