function routeCalendarContent(){const events=ROUTE_EVENTS.filter(e=>e.route===route).sort((a,b)=>a.chapter-b.chapter||String(a.start).localeCompare(String(b.start)));return `<section id="route-events"><h2>任务与观战日历</h2>${route!=='救世篇'?`<p class="calendar-note">${tag('观战开放 · 第'+CATALOG.arenaCalendar.unlock[route]+'章','key')}${esc(CATALOG.arenaCalendar.note)}</p>`:''}${chapterCalendar(events,route,'guide-'+route)}</section>`}
