function overview(){if(!guideViewOptions().some(([key])=>key===routeGuideView))routeGuideView='plan';if(routeGuideView==='plan')return cultivationOverview();let content='',heading='';if(routeGuideView==='pets'){content=kaiSection([...routeCandidates(),...routeSupplements()]);heading='捕获与骑兵'}else if(routeGuideView==='recruit'){recruitScope=route==='救世篇'?'common':route;const full=recruit();content=full.slice(full.indexOf('<div class="recruit-dashboard">'));heading='招募与声望'}else if(routeGuideView==='calendar'){content=routeCalendarContent();heading='任务与观战日历'}else {content=routeEquipmentContent();heading='装备与材料'}return `${routeCover(route)}<div id="route-guide-panel" role="tabpanel" aria-labelledby="${routeTabId(route)}" tabindex="0">${title('01 · 路线攻略',routes[route]+' · '+heading,'')}${preferenceEntry()}${guideContentTabs()}<section id="guide-content-${routeGuideView}" role="tabpanel" aria-labelledby="guide-view-${routeGuideView}">${content}</section></div>`}

function homeFaceRow(){const rank={'S+':0,'S':1,'S-':2,'A+':3,'A':4,'A-':5,'B':6,'C':7};return [...DB.characters].sort((a,b)=>(isPreferred(b)-isPreferred(a))||((rank[a.rating]??9)-(rank[b.rating]??9))||a.cn.localeCompare(b.cn,'zh')).slice(0,12).map(c=>`<a class="home-face" href="#character/${c.id}">${portrait(c)}<span class="home-face-copy"><b>${esc(c.cn)}</b><small>${esc(c.role)}</small></span>${ratingBadge(c,false,true)}</a>`).join('')}
