function homePage(){const feats=[['overview','路线攻略','四条主角线与第三部养成规划','M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4Z M12 6v16'],['characters','全角色图鉴','成长率、评级与职业方向','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-2a4 4 0 0 0-3-4 M16 3a4 4 0 0 1 0 8'],['recruit','招募与声望','答题、交涉、推荐礼物与时限','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8'],['map','探索大地图','商店商品与资源采集点位','m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Z M9 3v15 M15 6v15'],['equipment','装备与材料','武器性能、来源与材料反查','M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Z M12 7v10'],['classes','职业资格','成长修正、转职资格与熟练','m5 3 16 16 M19 3 3 19 M4 15l5 5 M15 4l5 5'],['calculator','自定义养成','按路线与入队时点试算成长','M4 21V3 M4 21h17 M8 16l4-5 4 2 5-7'],['guides','攻略文章','机制详解、外传与首领攻略','M4 5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0-2 2Z M4 21V5 M8 7h7 M8 11h7']],featuredIds=['blessings-guide','best-skills','phase-checklists','inheritance','part3-walkthrough','boss-strategies'],latest=featuredIds.map(id=>ARTICLES.find(a=>a.id===id)).filter(Boolean);return `<div class="home-page" data-skill-images="off">${annaHomeBlock()}<section class="home-section"><div class="home-section-head"><h2>五章命运 · 路线攻略</h2><a class="text-button" href="#overview">进入路线规划 ↗</a></div><div class="home-route-grid">${Object.entries(routes).map(([r,n])=>{const h=CATALOG.presentation.heroes.find(h=>h.route===r),c=h&&DB.characters.find(c=>c.id===h.id),tags=h?h.tags.slice(0,2):['成长融合','五队终局'];return `<button class="home-route-card" data-open-route="${escapeAttr(r)}">${c?portrait(c,true):`<img class="route-group-portrait" src="assets/route-group.svg" alt="四位主角">`}<span class="home-route-copy"><b>${n}${r==='救世篇'?' · 救世篇':'篇'}</b><small>${esc(h?.theme||'同伴合流 · 分队终局')}</small><span class="home-route-tags">${tags.map(t=>`<i>${esc(t)}</i>`).join('')}</span></span></button>`}).join('')}</div></section><section class="home-section"><div class="home-section-head"><h2>主力角色速览</h2><a class="text-button" href="#characters">全部角色 ↗</a></div><div class="home-face-grid">${homeFaceRow()}</div></section><section class="home-section"><div class="home-section-head"><h2>精选深度攻略</h2><a class="text-button" href="#guides">全部攻略 ↗</a></div><div class="home-article-grid">${latest.map(a=>`<a class="home-article-card" href="#guides/${esc(a.id)}"><div class="home-article-meta"><span class="home-article-cat">${esc(a.category)}</span><small>${a.sections.length}节 · 约${articleMinutes(a)}分钟</small></div><b>${esc(a.title)}</b><p>${esc(a.summary)}</p></a>`).join('')}</div></section><section class="home-section"><div class="home-section-head"><h2>账本工具与资料库</h2></div><div class="home-link-grid">${feats.map(([id,name,desc,icon])=>`<a class="home-link-card" href="#${id}"><span class="home-link-icon"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icon}"/></svg></span><span><b>${name}</b><small>${desc}</small></span></a>`).join('')}</div></section></div>`}
function cultivationOverview(){const cs=routeCandidates(),supplements=routeSupplements(),ids=new Set([...cs.map(c=>c.id),...supplements.map(c=>c.id)]),events=ROUTE_EVENTS.filter(e=>e.route===route).sort((a,b)=>a.chapter-b.chapter||String(a.start).localeCompare(String(b.start))),hasCalendar=route!=='救世篇'||events.length>0||(CATALOG.chapterCalendar.mainline[route]||[]).length>0;return `${routeCover(route)}<div id="route-guide-panel" role="tabpanel" aria-labelledby="${routeTabId(route)}" tabindex="0">${title('01 · 路线攻略',routes[route]+' · 培养与收集计划','')}${preferenceEntry()}${guideContentTabs()}<div id="guide-content-plan" role="tabpanel" aria-labelledby="guide-view-plan"><div class="guide-jump">${[['route-team','阵容与补强'],['route-arena','斗技场'],['route-fusion',route==='救世篇'?'分队规划':'跨线互补']].map(([id,n])=>`<button data-scroll="${id}">${n}</button>`).join('')}</div>${route==='救世篇'?`<div class="plan-dashboard"><article><strong>${new Set(cs.map(c=>c.id)).size}</strong><span>整合角色</span></article><article><strong>2 → 5</strong><span>分队规模</span></article></div>`:`<div class="plan-dashboard"><article><strong>${cs.length}</strong><span>重点候选</span></article><article><strong>${cs.filter(c=>!isSupplement(c,route)&&timing(c).priority===1).length}</strong><span>前期主力</span></article><article><strong>${supplements.length}</strong><span>候补补强</span></article></div>`}<section id="route-team"><h2>${route==='救世篇'?'整合阵容与分工':'培养阵容'}</h2>${routeStrategyPanel(cs)}<div class="priority-legend">${route==='救世篇'?tag('后期即战力','priority-p4'):tag('先养主力','priority-p1')+tag('中后期上场','priority-p2')+(supplements.length?tag('候补专项补强','priority-supp'):'')}</div>${growthLegend()}<div class="char-grid">${cs.map(card).join('')}</div>${supplements.length?`<h3>可选补强位 · 不占本线主力名额</h3><div class="char-grid supplementary-grid">${supplements.map(card).join('')}</div>`:''}</section><section id="route-arena"><h2>${route==='救世篇'?'第三部设施与培养':'斗技场训练'}</h2>${route==='救世篇'?part3Guide():''}${arenaViews([...cs,...supplements],'route-'+route)}</section><section id="route-fusion">${route==='救世篇'?thirdPartPlanning():preferencePlan()}</section></div></div>`}
function activateDetailRoute(button){if(!activeCharacter)return;const fromTab=!!button.closest('.dossier-tabs'),r=button.dataset.detailRoute;detailRoutes[activeCharacter]=r;delete selectedClasses[activeCharacter];characterMapArea=r==='summary'?'all':r;openCharacter(activeCharacter,true);if(fromTab)document.querySelector('.dossier-tabs [aria-selected="true"]')?.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{const target=e.target.closest?.('.dossier-tabs [data-detail-route]');if(!target||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...target.closest('.dossier-tabs').querySelectorAll('[role="tab"]')],i=buttons.indexOf(target),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;e.preventDefault();activateDetailRoute(buttons[next]);});
