function primaryValue(c){return PRIMARY_VALUE[c.id]||{primaryRoutes:[],optionalRouteIds:[],classification:'后期补入',analysis:'按已学能力补缺'}}
function isPrimaryHere(c,r){return primaryValue(c).primaryRoutes.includes(r)}
function isSupplement(c,r){return firstPartHere(c,r)&&!isPrimaryHere(c,r)&&!(r==='カイ'&&c.id==='c9')}
function trainingProfiles(c){const value=primaryValue(c),out={};for(const r of [...value.primaryRoutes,...value.optionalRouteIds]){const ed=editorRule(c,r),primary=value.primaryRoutes.includes(r);let kind=ed?(ed.goal.includes('防御')?'defense':ed.goal.includes('魔力')?'magic':ed.focus.includes('飞行术')||ed.focus.includes('马术')?'mount':'main'):primary?'main':'mastery';out[r]={...ed,kind,optional:!primary,label:primary?(ed?.label||value.archetypes.join(' / ')+'主培养'):ed?.optional?ed.label:'可选补修 · 不占主力名额'}}return out}
function routeCandidates(){if(route==='救世篇'){const lead=DB.characters.find(c=>c.id==='c58'),fav=DB.characters.filter(isPreferred),pool=DB.characters.slice().sort((a,b)=>RATING_TIERS.indexOf(a.rating)-RATING_TIERS.indexOf(b.rating));return [...new Map([lead,...fav,...pool].filter(Boolean).map(c=>[c.id,c])).values()].slice(0,25)}const plan=ROUTE_STRATEGY[route],ids=plan.core.map(c=>c.id),protectedIds=new Set([...plan.core.filter(c=>c.keepOpening).map(c=>c.id),...Object.values(plan.coverage).flat()]);for(const swap of plan.lateReplacements){if(!preferences.has(swap.id)||!isPrimaryHere(DB.characters.find(c=>c.id===swap.id),route))continue;const ix=ids.findIndex(id=>swap.replaces.includes(id)&&(!protectedIds.has(id)||route==='カイ'&&id==='c9'));if(ix>=0&&!ids.includes(swap.id))ids[ix]=swap.id}const extras=DB.characters.filter(c=>isPreferred(c)&&firstPartHere(c,route)&&isPrimaryHere(c,route)&&!ids.includes(c.id)).sort((a,b)=>routeCost(a,route)-routeCost(b,route)||RATING_TIERS.indexOf(a.rating)-RATING_TIERS.indexOf(b.rating));for(const c of extras){const ix=ids.map((id,i)=>({id,i})).reverse().find(x=>!protectedIds.has(x.id)&&!isPreferred(DB.characters.find(c=>c.id===x.id)));if(ix)ids[ix.i]=c.id;else if(ids.length<8)ids.push(c.id)}return ids.map(id=>DB.characters.find(c=>c.id===id)).filter(c=>c&&firstPartHere(c,route))}
function routeSupplements(){return route==='救世篇'?[]:DB.characters.filter(c=>isPreferred(c)&&isSupplement(c,route)&&!routeCandidates().some(x=>x.id===c.id)).sort((a,b)=>routeCost(a,route)-routeCost(b,route))}
function preferenceAssignments(){return DB.characters.filter(isPreferred).map(c=>({c,assigned:primaryValue(c).primaryRoute||'后期',possible:primaryValue(c).primaryRoutes}))}
