function sourceConflictReview(){
 const audit=CATALOG.dataResearch;if(!audit)return '';
 const label=u=>({'gamewith.jp':'GameWith','altema.jp':'Altema','gamecap.jp':'Gamecap','game8.jp':'Game8','cn.fire-emblem-fw.site':'中文攻略站','fire-emblem-fw.site':'中文攻略站旧记录','redfreshet.com':'redfreshet','www.gamersky.com':'游民星空'}[u.split('/')[2]]||'原始来源');
 const link=u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(label(u))} ↗</a>`;
 const table=(rows,resolved)=>`<div class="table-wrap"><table><thead><tr><th>数据项</th><th>${resolved?'采用值':'当前值'}</th><th>核对信源</th></tr></thead><tbody>${rows.map(c=>`<tr><td><b>${esc(c.subject)}</b></td><td>${esc(c.adopted||c.current)}</td><td>${(resolved?c.matchedSources:c.statements.map(s=>s.url)).map(link).join(' · ')}<details><summary>核对记录</summary>${c.statements.map(s=>`<p><b>${esc(s.value)}</b> · ${link(s.url)}<small>${esc(s.location)}</small></p>`).join('')}</details></td></tr>`).join('')}</tbody></table></div>`;
 return `<section class="source-conflicts"><h2>交叉核对与数据取值</h2><p>${esc(audit.policy)}</p>${audit.resolvedConflicts?.length?'<h3>已按一致记录采用</h3>'+table(audit.resolvedConflicts,true):''}${audit.conflicts?.length?'<h3>仍有冲突 · 待判断</h3>'+table(audit.conflicts,false):'<p class="muted">本轮发现的数值冲突均已有两站一致记录；历史分歧保留在核对记录中。</p>'}<h2>尚未补齐的资料</h2><p>${esc(audit.remaining)}</p><div class="table-wrap"><table><thead><tr><th>类别</th><th>待核实内容</th></tr></thead><tbody>${(audit.remainingItems||[]).map(g=>`<tr><td>${esc(g.subject)}</td><td>${esc(g.items.join('、'))}</td></tr>`).join('')}</tbody></table></div><details><summary>技能学习条件 · ${audit.remainingCounts?.skillRequirements||0}条待核实</summary><div class="table-wrap"><table><thead><tr><th>角色</th><th>待核实技能条件</th></tr></thead><tbody>${(audit.remainingLearning||[]).map(c=>`<tr><td><button class="entity-link" data-char="${esc(c.id)}">${esc(c.name)}</button></td><td>${esc(c.skills.join('、'))}</td></tr>`).join('')}</tbody></table></div></details></section>`
}
function routeMap(cs){if(!mapLoaded){loadMap();return loadingBlock('正在载入路线地图…')}const q=routeMapQueries[route]||'',items=selectedGear(equipmentEntries(cs),'route:'+route),terms=[...new Set(items.flatMap(x=>[x.source?.place,...x.mats.map(m=>m[0])]).filter(Boolean))];const list=PINS.filter(p=>p.area===route&&(q?mapMatches(p,q):true));return `${route==='救世篇'?'<p class="muted">第三部点位尚未完整收录；第一部地点不能直接视为第三部已开放。</p>':''}<div class="route-map-tools">${searchField({attrs:'data-route-map-search',value:q,placeholder:'搜索本线材料或地点',label:'搜索本线地图',kbd:false})}<div><button data-zoom="1">＋</button><button data-zoom="-1">−</button><button data-zoom="0">复位</button></div></div><div class="map-shortcuts"><button data-route-map-term="" class="${q?'':'active'}">全路线</button>${terms.map(t=>`<button data-route-map-term="${esc(t)}" class="${q===t?'active':''}">${esc(t)}</button>`).join('')}</div>${mapMarkup(list,true)}`}
