// Sequential three-anchor palette with perceptual interpolation and full cell contrast.
function growthDomain(modifier=null){const values=DB.characters.flatMap(c=>Object.keys(statNames).map(k=>Number(c.growth[k]||0)+Number(modifier?.[k]||0)));return [Math.min(...values),Math.max(...values)]}
function growthColor(v,domain=growthDomain()){const [lo,hi]=domain,t=Math.max(0,Math.min(.999999,(v-lo)/(hi-lo||1)));return GROWTH_PALETTE[Math.floor(t*GROWTH_PALETTE.length)]}
function heat(g,modifier=null,layout='card'){const domain=growthDomain(modifier),cell=k=>{const base=Number(g[k]||0),delta=Number(modifier?.[k]||0),v=base+delta,values=DB.characters.map(c=>Number(c.growth[k]||0)),pct=(values.filter(x=>x<base).length+values.filter(x=>x===base).length*.5)/values.length,label=pct>=.75?'较高':pct<=.25?'较低':'中等';return `<div class="heat-cell" data-stat="${k}" style="--growth-color:${growthColor(v,domain)}" title="${statNames[k]}：基础 ${base}%${modifier?'＋职业修正 '+delta+'＝总成长 '+v+'%':''}；基础成长相对全图鉴同属性${label}"><small>${statNames[k]}</small><div class="growth-value"><b>${v}<sup>%</sup></b>${modifier?`<span class="growth-delta ${delta>0?'positive':delta<0?'negative':'neutral'}" aria-label="职业修正${delta}个百分点">${delta>0?'+':''}${delta}</span>`:''}</div>${modifier?'':`<span class="growth-strength">${label}</span>`}</div>`};return `<div class="heat-grid heat-${layout}">${['str','mag','spd','hp','def','res','dex','lck','cha'].map(cell).join('')}</div>`}
function growthLegend(modifier=null){const [lo,hi]=growthDomain(modifier);return `<div class="growth-legend"><span>${lo}%</span><div class="growth-swatches" aria-hidden="true">${GROWTH_PALETTE.map(c=>`<i style="background:${c}"></i>`).join('')}</div><span>${hi}%</span><small>${modifier?'右侧为职业修正':'较高 / 较低按同属性比较'}</small></div>`}
function joinBadges(c,r=routeContext(c)){if(r==='summary')return `<div class="join-badges">${tag(c.firstPart?'第一部可培养':'后期 / 固定战力')}${tag(primaryValue(c).primaryRoutes.length?'主养 '+primaryValue(c).primaryRoutes.map(r=>routes[r]).join(' / '):'后续 / 序幕固定战力','key')}${tag('终局 · '+finalBuild(c).end)}</div>`;if(r!=='救世篇'&&!firstPartHere(c,r))return '';const t=timing(c,r),supp=isSupplement(c,r),p=supp?3:t.priority===3?4:t.priority;return `<div class="join-badges">${tag(({1:'优先主力',2:'中后期上场',3:'候补专项补强',4:'后期即战力'}[p]),p===3?'priority-supp':'priority-p'+p)}${tag(t.story?'剧情入队':t.renown?'声望 '+t.renown:'门槛见入队表')}${t.chap?tag('初见第'+t.chap+'章'):''}${t.quest.length?tag('需第'+t.quest[0].chapter+'章外传','key'):''}</div>`}
function routeProfileTable(c){const rs=Object.keys(routes).filter(r=>r!=='救世篇'&&firstPartHere(c,r)),profiles=trainingProfiles(c);return (rs.length?`<div class="table-wrap"><table class="profile-table compact-plan-table"><thead><tr><th>可培养路线 / 时点</th><th>互补培养</th><th>技能与最终用途</th></tr></thead><tbody>${rs.map(r=>{const p=profiles[r],b=buildPlan(c,r);return `<tr><td>${routeIdentity(r)}<small>${esc(joinTextFor(c,r))}</small></td><td><b>${p?.optional?'补强 · ':''}${esc(p?.label||'主职责培养')}</b><small>${complementStages(c,b)}</small></td><td>${esc(b.focus)}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="muted">本角色没有可培养的第一部主角路线，按共通 / 后续入队能力直接补强。</p>')+`<div class="fusion-result">${tag('第三部整合')}<b>${finalBuild(c).end}</b><p>选需要的培养成果与补修即可；属性融合逐项取高，临时职业加成不算永久收益。</p></div>`}
function projectSuggestions(c){const goals=skillTargets(c);return ARENA_PROJECTS.map(p=>({...p,targets:goals.filter(t=>p.skills.includes(t.skill))})).filter(p=>p.targets.length).sort((a,b)=>b.targets.length-a.targets.length)}
function arenaPeople(people,compact){const render=({c,goals})=>compact?`<div class="training-goals">${goals.map(t=>tag(t.skill+" "+t.rank,"key")).join("")}</div>`:arenaPerson(c,`${portrait(c)}<span class="table-character-copy"><b>${c.cn}</b><small class="arena-goal-list">${goals.map(t=>`<span class="arena-goal"><span>${esc(t.skill)}</span><span class="arena-goal-rank">${esc(t.rank)}</span></span>`).join("")}</small></span>`);return `<div class="training-people">${[...people].sort((a,b)=>Number(isPreferred(b.c))-Number(isPreferred(a.c))).map(render).join("")}</div>`}

function arenaTable(cs,compact=false){const phase3=guidePage()==='overview'&&route==='救世篇'||activeCharacter&&dataRoute(DB.characters.find(c=>c.id===activeCharacter))==='summary'&&!DB.characters.find(c=>c.id===activeCharacter).firstPart;const targets=cs.map(c=>({c,goals:skillTargets(c)}));const rows=ARENA_PROJECTS.map(p=>({p,people:targets.map(({c,goals})=>({c,goals:goals.filter(t=>p.skills.includes(t.skill))})).filter(x=>x.goals.length)}));const missing=targets.flatMap(({c,goals})=>goals.filter(t=>!ARENA_PROJECTS.some(p=>p.skills.includes(t.skill))).map(t=>({c,...t})));return `${phase3?'<div class="note">第三部需先重建大斗技场；未重建时用战斗和候补待机经验准备。</div>':''}<div class="arena-rules"><span>每项目每周一次 · 每次2人</span><span>五种项目池 · 当周四种</span><span>6:00–23:59 · 大斗技场前</span><span>通常干劲1 · 周末半价</span></div>${compact?'':arenaLegend(cs)}<div class="table-wrap"><table class="arena-direction-table ${compact?'current-target-table':''}"><thead><tr><th>训练项目</th><th>同时提升的技能</th><th>${compact?'当前目标':'推荐角色 / 当前目标'}</th><th>重点属性与升级职业</th></tr></thead><tbody>${rows.filter(({people})=>people.length||!compact).map(({p,people})=>`<tr><td><b>${p.name}</b><small>按当周菜单选择</small></td><td><div class="arena-skill-bundle">${p.skills.map(s=>tag(s,'key')).join('')}</div></td><td>${people.length?arenaPeople(people,compact):'本阵容暂无重点训练目标'}</td><td>${[...new Set(people.flatMap(x=>x.goals.map(g=>arenaAttributes[g.skill])))].join('；')||'按角色职责'}<small>${[...new Set(people.flatMap(x=>x.goals.map(g=>g.cl)))].map(n=>referenceLink('class',n,n)).join(' / ')}</small></td></tr>`).join('')}</tbody></table></div><p class="muted">训练只增加技能经验，不增加永久属性；当周最多训练4次。${articleLink('arena','完整训练规则')}</p>${missing.length?note('以下训练目标不在已核实的五种训练组合内：'+missing.map(t=>t.c.cn+' · '+t.skill+' '+t.rank).join('；')+'。需用指南书、战斗或其他培养方式补齐，不新增虚构训练项目。'):''}`}
function training(){const list=DB.characters.filter(c=>searchText(c).includes(query.toLowerCase()));return title('全局训练资料','技能与斗技场','')+filterDeck(toolbar('搜索角色…',searchCount(list.length,DB.characters.length,'名角色')))+arenaViews(list,'global')+`<p class="muted">${link('https://gamewith.jp/fefw/576868','训练组合与经验资料')} · ${link('https://game8.jp/fe-banshisenko/816482','重装训练与开放时段')} · ${link('https://appmedia.jp/fe_banshisenkou/80399233','菜单轮换与各线开放章节')}</p>`+`<div class="arena-rules"><span>凯伊 · 第5章</span><span>迪托利希 · 第5章</span><span>赛奥朵拉 · 第4章</span><span>蕾达 · 第5章</span></div>`+arenaObservationCalendar()+trainingReferenceNotes()}

function lineupFor(r){const saved=route;try{route=r;return routeCandidates()}finally{route=saved}}
function thirdPartPlanning(){const plans=Object.keys(ROUTE_STRATEGY).map(r=>({r,cs:lineupFor(r)})),unique=new Set(plans.flatMap(p=>p.cs.map(c=>c.id))),slots=plans.reduce((n,p)=>n+p.cs.length,0);return `<h2>第三部分队 · 四线成果整合</h2><p class="muted">以开局骨架和职责覆盖为先；同角色融合后只算一人，晚加入角色继续补齐编制。</p>`+`<div class="stats"><div class="stat"><strong>${slots}</strong><div><b>各线培养席位</b><small>包含互补培养的重复角色</small></div></div><div class="stat"><strong>${unique.size}</strong><div><b>独立角色</b><small>按当前偏好推荐去重</small></div></div><div class="stat"><strong>2 → 5</strong><div><b>第三部部队数</b><small>早期2队，后续最多5队</small></div></div></div><div class="table-wrap"><table><thead><tr><th>路线</th><th>当前推荐</th><th>前排 / 治疗 / 远程 / 魔法</th></tr></thead><tbody>${plans.map(({r,cs})=>`<tr><td>${routes[r]}</td><td>${cs.map(c=>`<button class="text-button" data-char="${c.id}">${c.cn}</button>`).join(' / ')}</td><td>${Object.entries(ROUTE_STRATEGY[r].coverage).map(([role,ids])=>role+'：'+ids.map(id=>r==='カイ'&&id==='c9'&&cs.some(c=>c.id==='c11')?'妮涅':DB.characters.find(c=>c.id===id)?.cn).join(' / ')).join('；')}</td></tr>`).join('')}</tbody></table></div><h2>五队职责框架</h2><div class="squad-grid">${['主角攻坚','机动突击','远程压制','魔法破防','防线支援'].map((n,i)=>`<article class="feature"><h3>${n}</h3><p>${[['主角 / 救世主','近战输出','远程','治疗','机动或再行动'],['骑飞输出','物理近战','弓或魔法','治疗','第二机动'],['弓核心','第二输出','前排','治疗','功能位'],['法术核心','第二法师或魔法剑','物理前排','治疗','机动'],['稳定前排','物理输出','远程','治疗','缺口替补']][i].join(' + ')}</p></article>`).join('')}</div><p class="muted">第三部第三区分3队，后续最多5队；第五区分按五队准备。治疗与远程分散配置，再行动角色按分队需求配置。晚加入的欧露赫露、爱娜特莉亚等可补战力缺口，不必第一部把所有角色练满。</p>`}
function planning(){return thirdPartPlanning()}

const RATING_TIERS=['S','S-','A+','A','A-','B','C'];
function arenaIsSupplement(c){return guidePage()==='overview'?isSupplement(c,route):activeCharacter===c.id&&dataRoute(c)!=='summary'&&isSupplement(c,dataRoute(c))}
function arenaPerson(c,content){const supplement=arenaIsSupplement(c);return `<button class="arena-person ${supplement?'arena-supplement':'arena-core'}" data-char="${c.id}" aria-label="${c.cn}，${supplement?'候补补强':'主力候选'}">${content}</button>`}
function arenaLegend(cs){return cs.some(arenaIsSupplement)?'<div class="arena-legend"><span><i class="arena-core"></i>主力候选</span><span><i class="arena-supplement"></i>候补补强</span></div>':''}

const GROWTH_PALETTE=['#f8f0df','#f6e5bd','#f3d392','#edbe70','#e5a35e','#d58c5d','#c87752','#b96448'];
let materialInventory={};try{const saved=JSON.parse(localStorage.getItem('fw-material-inventory-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [name,n]of Object.entries(saved))if(Number.isFinite(Number(n)))materialInventory[name]=Math.max(0,Math.min(999999,Math.floor(Number(n))))}catch{}
function materialOwned(name){return materialInventory[name]||0}
function materialInventoryTable(totals,scope){return `<div class="material-summary"><h3>剩余材料收集 ${tag(totals.length+'种')}</h3>${totals.length?`<div class="table-wrap"><table class="inventory-table"><thead><tr><th>材料</th><th>需要</th><th>已有 · 可填写</th><th>还缺</th><th>使用装备 / 地点</th></tr></thead><tbody>${totals.map(({m,qty,uses})=>{const own=materialOwned(m[0]),lack=Math.max(0,qty-own);return `<tr><td><button class="text-button" ${scope.startsWith('char:')?'data-character-material':'data-map'}="${esc(m[0])}">${esc(m[0])}</button></td><td><b>${qty}</b></td><td><input class="inventory-input" type="number" min="0" max="999999" step="1" inputmode="numeric" value="${own}" data-material-stock="${esc(m[0])}" aria-label="${esc(m[0])}已有数量"></td><td><span class="inventory-gap ${lack?'pending':'complete'}">${lack||'已齐'}</span></td><td><small>${esc(uses.join(' / '))}</small>${esc(m[3])}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="muted">当前没有待兑换装备的材料需求。</p>'}</div>`}
function planMobility(c){if(!canRide(c))return '';const b=buildPlan(c,route),names=[b.mid[0],b.upper[0]],cls=names.map(classBy).filter(Boolean),has=skill=>cls.some(cl=>[...(cl.must||[]),...(cl.any||[])].some(x=>x[0]===skill));return [has('马术')?'骑兵':'',has('飞行术')?'飞行':''].filter(Boolean).join(' / ')}
function routeCoverage(cs){
 const ids=new Set(cs.map(c=>c.id)),coverage={};
 for(const [role,members] of Object.entries(ROUTE_STRATEGY[route].coverage))coverage[role]=[...new Set(members.map(id=>route==='カイ'&&id==='c9'&&ids.has('c11')?'c11':id).filter(id=>ids.has(id)))];
 Object.assign(coverage,{'近战':[],'骑兵':[],'飞行':[]});
 const add=(role,c)=>{coverage[role]??=[];if(!coverage[role].includes(c.id))coverage[role].push(c.id)};
 for(const c of cs){
  const b=buildPlan(c,route),classes=[b.mid[0],b.upper[0]].map(classBy).filter(Boolean);
  // Magic alternatives on a class qualification do not establish both casting roles.
  const has=(cl,skill)=>(cl.must||[]).some(x=>x[0]===skill)||(cl.any||[]).some(x=>x[0]===skill)&&!(['黑魔术','白魔术'].includes(skill)&&(cl.any||[]).some(x=>x[0]===(skill==='黑魔术'?'白魔术':'黑魔术')));
  if(classes.some(cl=>has(cl,'重装术')))add('坦克',c);
  if(classes.some(cl=>has(cl,'白魔术')))add('治疗',c);
  if(classes.some(cl=>has(cl,'弓术')))add('弓',c);
  if(classes.some(cl=>has(cl,'黑魔术')))add('魔法',c);
  if(!coverage['坦克'].includes(c.id)&&classes.some(cl=>cl.cn!=='舞者'&&!has(cl,'黑魔术')&&!has(cl,'白魔术')&&['剑术','枪术','斧术','格斗术'].some(skill=>has(cl,skill))))add('近战',c);
  for(const role of ['骑兵','飞行'])if(planMobility(c).includes(role))add(role,c);
 }
 const covered=new Set(Object.values(coverage).flat()),other=cs.filter(c=>!covered.has(c.id)).map(c=>c.id);
 if(other.length)coverage['专项支援']=other;
 return coverage;
}
function toggleSidebar(force){const collapsed=typeof force==='boolean'?force:!document.body.classList.contains('sidebar-collapsed');document.body.classList.toggle('sidebar-collapsed',collapsed);const button=$('#sidebarToggle');button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',collapsed?'展开攻略目录':'折叠攻略目录');button.innerHTML=sidebarIcon(collapsed);try{localStorage.setItem('fw-sidebar-collapsed-v1',String(collapsed))}catch{}}
$('#sidebarToggle').addEventListener('click',()=>toggleSidebar());try{toggleSidebar(localStorage.getItem('fw-sidebar-collapsed-v1')==='true')}catch{}

let weaponInventory=readCountStorage('fw-weapon-inventory-v1');gearSources=readCountStorage('fw-gear-sources-v1');
function readCountStorage(key){const out={};try{const saved=JSON.parse(localStorage.getItem(key)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [name,n]of Object.entries(saved))if(Number.isFinite(Number(n)))out[name]=Math.max(0,Math.min(999999,Math.floor(Number(n))))}catch{}return out}
function weaponInventoryTable(items,characterOnly=false){return `<section class="weapon-summary"><h3>武器 / 装备收集</h3><div class="table-wrap"><table class="weapon-inventory-table"><thead><tr><th>武器 / 装备</th>${characterOnly?'':'<th>需求角色</th>'}<th>需要</th><th>已有 · 可填写</th><th>还缺</th><th>获取途径</th></tr></thead><tbody>${items.map(item=>{const {e,qty,owned,remaining,source,buy,exchange}=item;return `<tr><td>${referenceLink('equipment',e.id,e.name)}</td>${characterOnly?'':`<td><div class="gear-demand-users">${item.users.length?stackedCharacters(item.users.map(c=>c.id)):'队伍共用'}</div></td>`}<td>${qty}</td><td><input class="inventory-input" type="number" min="0" max="999999" step="1" inputmode="numeric" value="${owned}" data-weapon-stock="${e.id}" aria-label="${esc(e.name)}已有数量"></td><td><span class="inventory-gap ${remaining?'pending':'complete'}">${remaining||'已齐'}</span></td><td>${sourcePicker(item)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function sidebarIcon(collapsed){return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${collapsed?'<path d="M4 6h16M4 12h16M4 18h16"/>':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16m7-12-4 4 4 4"/>'}</svg>`}
function casterSupplementGuide(c){if(!/魔法|治疗/.test(c.role))return '';return `<section class="caster-supplement"><h3>法师副职：补缺口再投入</h3><p class="healer-policy">${esc(CATALOG.crossRoutePolicy.healer)}</p><div class="table-wrap"><table><thead><tr><th>需求</th><th>值得补什么</th><th>停止条件</th></tr></thead><tbody><tr><td>治疗 / 法术主职责未完成</td><td>优先白魔 / 黑魔资格、魔力和核心功能</td><td>先完成本线主职，不为副职推迟成型</td></tr><tr><td>兼顾攻击 / 防追击，且负重拖慢攻速</td><td>先减轻装备；仍有缺口再用勇士补力量</td><td>每5力量约增1体格；达到实际重量需求就停</td></tr><tr><td>要兼任弓手，或专补技巧 / 速度</td><td>已有弓B时可考虑狙击手；熟练只强化弓命中</td><td>纯治疗不默认投入弓B，取得指定成果后回主职</td></tr></tbody></table></div><p class="muted">示例：同样实际升级20次，狙击手相比主教的期望增量约为力量＋2、速度＋2、技巧＋3；勇士相比主教约多5力量，可跨过约1点体格门槛。只是期望，不保证成长；融合取各项较高值，不能把这些增量直接相加。永久成长靠升级取得，职业面板加成切走后不保留。</p></section>`}

let dialogScrollState=null,backdropTouchY=null;
function openGuideDialog(d=$('#detail')){const heading=d.querySelector("h1,h2,h3");if(heading){heading.id=d.id+"-heading";d.setAttribute("aria-labelledby",heading.id)}else d.setAttribute("aria-label","攻略详情");if(d.open)return;const body=document.body,x=Number(window.scrollX||0),y=Number(window.scrollY||0),styles={};for(const k of ['position','top','left','width','paddingRight'])styles[k]=body.style[k]||'';dialogScrollState={x,y,hash:location.hash,focus:document.activeElement,styles};body.style.position='fixed';body.style.top=-y+'px';body.style.left=-x+'px';body.style.width='100%';const gutter=Math.max(0,(window.innerWidth||0)-(document.documentElement?.clientWidth||window.innerWidth||0));if(gutter)body.style.paddingRight=`calc(${styles.paddingRight||'0px'} + ${gutter}px)`;body.classList.add('modal-open');try{d.showModal()}catch(e){releaseDialogScroll();throw e}}
function releaseDialogScroll(){const saved=dialogScrollState;if(!saved)return;dialogScrollState=null;for(const [k,v]of Object.entries(saved.styles))document.body.style[k]=v;document.body.classList.remove('modal-open');if(location.hash===saved.hash){saved.focus?.focus?.({preventScroll:true});window.scrollTo({left:saved.x,top:saved.y,behavior:'instant'})}}
$('#detail').addEventListener('wheel',e=>{if(outsideDialog(e,$('#detail')))e.preventDefault()},{passive:false});
$('#detail').addEventListener('touchstart',e=>{const t=e.touches?.[0];backdropTouchY=t&&outsideDialog({target:e.target,clientX:t.clientX,clientY:t.clientY},$('#detail'))?t.clientY:null},{passive:true});
$('#detail').addEventListener('touchmove',e=>{if(backdropTouchY!==null)e.preventDefault()},{passive:false});
$('#detail').addEventListener('touchend',()=>{backdropTouchY=null},{passive:true});
function initialPlan(c,b=buildPlan(c)){const p=CATALOG.planning[c.id];return Object.values(p.routes).find(v=>v.build===b)?.initial||p.initial}

const careerStages={},arenaViewState={};
function escapeAttr(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const sourcePickerItems=new Map();let sourceDialogOwnsLock=false,sourceDialogBackdrop=false;
function sourcePicker(item){sourcePickerItems.set(item.key,item);const label=(item.source?.kind||'待核对')+(item.remaining?' × '+item.remaining:' · 已齐');return `<button type="button" class="source-picker-trigger" data-open-source="${escapeAttr(item.key)}" aria-haspopup="dialog" aria-label="${esc(item.e.name)}：${esc(label)}，更换获取途径，共${item.e.sourcesList.length}种" title="${esc(item.source?.text||'更换获取途径')}"><span class="source-picker-value">${esc(label)}</span><small class="source-picker-count">${item.e.sourcesList.length}种</small><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg></button>`}

function sourceDialogMarkup(item){const {e,key,idx}=item;return `<div class="source-dialog-head"><h2 id="source-dialog-title">${esc(e.name)} · 获取途径</h2><p>选择一种途径，按尚缺装备的份数更新材料需求。</p></div><div class="source-choices source-dialog-options">${e.sourcesList.map((source,i)=>`<button type="button" data-gear-source="${escapeAttr(key)}" data-source-index="${i}" aria-pressed="${idx===i}" class="${idx===i?'selected':''}">${sourceOptionContent(e,source,false,idx===i?'✓ 当前':'选择')}</button>`).join('')}</div>`}
function openSourceDialog(key){const item=sourcePickerItems.get(key);if(!item)return;const d=$('#sourceDialog');$('#sourceDialogContent').innerHTML=viewHTML(sourceDialogMarkup(item));sourceDialogOwnsLock=!$('#detail').open;if(sourceDialogOwnsLock)openGuideDialog(d);else d.showModal();d.scrollTop=0;}
$('#sourceDialog').addEventListener('close',()=>{if(sourceDialogOwnsLock){sourceDialogOwnsLock=false;releaseDialogScroll();}});
$('#sourceDialog').addEventListener('pointerdown',e=>{sourceDialogBackdrop=outsideDialog(e,$('#sourceDialog'))});
$('#sourceDialog').addEventListener('click',e=>{if(sourceDialogBackdrop&&outsideDialog(e,$('#sourceDialog')))$('#sourceDialog').close();sourceDialogBackdrop=false});
$('#sourceDialog').addEventListener('wheel',e=>{if(outsideDialog(e,$('#sourceDialog')))e.preventDefault()},{passive:false});
let sourceBackdropTouch=false;$('#sourceDialog').addEventListener('touchstart',e=>{const t=e.touches?.[0];sourceBackdropTouch=!!t&&outsideDialog({target:e.target,clientX:t.clientX,clientY:t.clientY},$('#sourceDialog'))},{passive:true});
$('#sourceDialog').addEventListener('touchmove',e=>{if(sourceBackdropTouch)e.preventDefault()},{passive:false});
$('#sourceDialog').addEventListener('touchend',()=>{sourceBackdropTouch=false},{passive:true});

function activateViewTab(button){const group=button.closest('[data-view-group]'),key=group.dataset.viewGroup,kind=group.dataset.viewKind,value=button.dataset.viewTab;if(kind==='career')careerStages[key]=Number(value);else arenaViewState[key]=value;for(const b of group.querySelectorAll('[data-view-tab]')){const active=b.dataset.viewTab===value;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;b.classList.toggle('active',active)}for(const panel of group.querySelectorAll('[data-view-panel]'))panel.hidden=panel.dataset.viewPanel!==value}
function arenaCharacterTable(cs){return `${arenaLegend(cs)}<div class="table-wrap"><table class="arena-character-table"><thead><tr><th>角色 / 分工</th><th>推荐训练项目</th><th>技能停止线</th><th>重点属性与职业</th></tr></thead><tbody>${cs.map(c=>{const b=buildPlan(c),goals=skillTargets(c);return `<tr><td>${tableCharacter(c,{tone:arenaIsSupplement(c)?'arena-supplement':'arena-core',showRating:false,subtitle:arenaRecommendedSubtitle(c)})}</td><td>${projectSuggestions(c).map(p=>tag(p.name,'key')).join('')||'需其他训练方式'}</td><td>${emphasis(editorRule(c,routeContext(c))?.firstPartStop||c.stop)}</td><td>${esc(b.focus)}<small>${complementStages(c,b)}</small></td></tr>`}).join('')}</tbody></table></div>`}
function arenaViews(cs,key){const value=arenaViewState[key]||'projects',id='arena-'+key.replace(/[^a-zA-Z0-9-]/g,'')+'-'+Object.keys(arenaViewState).length;return `<div class="view-switcher arena-views" data-view-group="${escapeAttr(key)}" data-view-kind="arena"><div class="view-tabs" role="tablist" aria-label="斗技场查看维度">${[['projects','按项目'],['characters','按角色']].map(([v,n])=>`<button id="${id}-tab-${v}" role="tab" data-view-tab="${v}" aria-selected="${value===v}" aria-controls="${id}-panel-${v}" tabindex="${value===v?0:-1}" class="${value===v?'active':''}">${n}</button>`).join('')}</div><section role="tabpanel" data-view-panel="projects" id="${id}-panel-projects" aria-labelledby="${id}-tab-projects" ${value==='projects'?'':'hidden'}>${arenaTable(cs)}</section><section role="tabpanel" data-view-panel="characters" id="${id}-panel-characters" aria-labelledby="${id}-tab-characters" ${value==='characters'?'':'hidden'}>${arenaCharacterTable(cs)}</section></div>`}
document.addEventListener('keydown',e=>{const target=e.target.closest?.('[data-view-tab]');if(!target||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...target.closest('[data-view-group]').querySelectorAll('[data-view-tab]')],i=buttons.indexOf(target),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;e.preventDefault();activateViewTab(buttons[next]);buttons[next].focus({preventScroll:true})});

function materialsForSource(e,source){if(/购买/.test(source?.kind||'')||source?.recipePending)return [];if(Array.isArray(source?.materials))return source.materials;let mats=e.materials.filter(m=>source?.text.includes(m[0]));if(/兑换/.test(source?.kind||source?.text||'')&&!mats.length&&e.sourcesList.filter(s=>/兑换/.test(s.kind||s.text)).length===1)mats=e.materials;return mats;}
const SKILL_ICON_FILES={'剑术':'sword','枪术':'lance','斧术':'axe','弓术':'bow','格斗术':'fist','黑魔术':'black-magic','白魔术':'white-magic','马术':'horse','飞行术':'flight','重装术':'armor','步兵术':'infantry','指挥术':'command'};
function skillAffinity(c,cl=null){const good=new Set((c.good||'').split(':').map(skillName)),bad=new Set((c.bad||'').split(':').map(skillName)),withClass=!!cl,allowed=new Set([...(cl?.allowedSkills||[]),'指挥术']);return `<section class="affinity-section ${withClass?'affinity-class-preview':''}" aria-label="${withClass?'当前职业技能可用性与资质':'技能资质'}"><div class="affinity-heading"><h3>技能资质</h3><span class="affinity-legend"><span class="affinity-good">${affinityStatusIcon('good')} 擅长</span><span>${affinityStatusIcon('neutral')} 普通</span><span class="affinity-bad">${affinityStatusIcon('bad')} 不擅长</span></span></div>${withClass?'<div class="class-skill-legend"><span class="skill-available-key">本职业可用</span><span>低亮项为本职业不可用；指挥术通用，资质不随职业改变</span></div>':''}<div class="affinity-grid">${Object.values(DB.skills).map(name=>{const state=bad.has(name)?'bad':good.has(name)?'good':'neutral',label=state==='good'?'擅长':state==='bad'?'不擅长':'普通',usable=allowed.has(name),status=withClass?(usable?'本职业可用':'本职业不可用'):'';return `<div class="affinity-item affinity-${state}${withClass?' '+(usable?'skill-available':'skill-unavailable'):''}" data-affinity-skill="${name}" ${withClass?`data-class-usable="${usable}"`:''} title="${name}：${label}${status?' · '+status:''}"><img class="skill-game-icon" src="assets/skills/${SKILL_ICON_FILES[name]}.webp" width="24" height="24" alt="" aria-hidden="true" decoding="async"><span>${name}</span><b aria-label="${label}${status?'，'+status:''}">${affinityStatusIcon(state)}</b></div>`}).join('')}</div></section>`;}
function routeIdentity(r,interactive=true){const hero=CATALOG.presentation.heroes.find(h=>h.route===r),c=hero&&DB.characters.find(c=>c.id===hero.id);if(!c)return `<span class="route-identity" data-skill-images="off">${esc(r==='共通'?'共通 / 后期':routes[r]||r)}</span>`;const inner=portrait(c)+`<span>${esc(routes[r]||c.cn)}</span>`;return interactive?`<button class="route-identity" data-detail-route="${r}" data-skill-images="off" aria-label="查看当前角色的${esc(routes[r])}路线">${inner}</button>`:`<span class="route-identity" data-skill-images="off">${inner}</span>`;}

function cardCareer(c,b=buildPlan(c)){const early=initialPlan(c,b),stages=[['初级',early.skip?'无需回练':early.name],['中级',b.mid.join(' / ')],['上级',b.upper.join(' / ')],['终局',b.end]];return `<div class="card-career-modern"><div class="card-career-label"><span>职业路线</span><b>${esc(profileName(c))}</b></div><ol class="mini-career-track">${stages.map(([label,name],i)=>`<li class="${i===0&&early.skip?'skipped-stage':''}"><span class="mini-step"><i>${i+1}</i><small>${label}</small></span>${name==='无需回练'?`<b>${esc(name)}</b>`:`<div class="mini-career-options">${name.split(/\s*[／/]\s*/).filter(Boolean).map(option=>`<button class="mini-career-link" data-reference-type="class" data-reference-id="${escapeAttr(option)}" title="${esc(option)}">${esc(option)}</button>`).join('')}</div>`}</li>`).join('')}</ol></div>`;}

function referenceLink(type,id,name){return `<button class="reference-link" data-reference-type="${type}" data-reference-id="${escapeAttr(id)}" aria-haspopup="dialog">${esc(name)}<span aria-hidden="true">↗</span></button>`;}
function referenceMarkup(type,id){if(type==='equipment'){const e=EQUIPMENT.find(e=>e.id===id);if(!e)return '';return `<div class="source-dialog-head weapon-visual-heading" data-skill-images="off"><div class="weapon-icon">${equipmentIcon(e)}</div><div><h2 id="source-dialog-title">${esc(e.name)}</h2><p>${esc(e.type)} · ${esc(e.phase)} · ${esc(e.rank)}</p></div></div><div class="reference-facts"><dl class="weapon-stat-grid">${equipmentMetrics(e).map(([,label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><h3>性能与用途</h3><p>${esc(e.effect)}</p><p>${esc(e.purpose)}</p>${equipmentVariants(e)}${equipmentSourcesInline(e)}</div>`;}const cl=classBy(id);if(!cl)return '';return `<div class="source-dialog-head class-dialog-head">${classIcon(cl,52)}<div><h2 id="source-dialog-title">${esc(cl.cn)}</h2><p class="heading-meta">${esc(cl.col_1)}</p></div></div><div class="reference-facts"><h3>职业资格</h3><p>${esc(requirement(cl))}</p><p>${tag('等级 '+(cl.col_31||'特殊'))}${tag('声望 '+(cl.col_32||'特殊'))}${tag('移动 '+(cl.col_34||'—'))}</p><h3>成长率修正</h3>${signedGrowth(cl)}<dl class="reason-facts"><div><dt>可用技能</dt><dd>${(cl.allowedSkills||[]).map(n=>tag(n)).join('')}</dd></div><div><dt>熟练奖励</dt><dd>${masteryFact(cl)}</dd></div><div><dt>考试凭证</dt><dd>${esc(cl.col_41||'特殊')}</dd></div><div><dt>解锁前置</dt><dd>${esc(cl.unlock||'无额外事件记录')}</dd></div></dl></div>`;}
function openReferenceDialog(type,id){const html=referenceMarkup(type,id);if(!html)return;const d=$('#sourceDialog');$('#sourceDialogContent').innerHTML=viewHTML(html);sourceDialogOwnsLock=!$('#detail').open;if(!d.open){if(sourceDialogOwnsLock)openGuideDialog(d);else d.showModal();}d.scrollTop=0;}

const searchCache=new WeakMap();
function searchText(c){if(!searchCache.has(c))searchCache.set(c,JSON.stringify(c).toLowerCase());return searchCache.get(c)}
function complementStages(c,b){const initial=initialPlan(c,b);return `<span class="complement-stages"><span><i>初</i>${initial.skip?'按入队职业':referenceLink('class',initial.name,initial.name)}</span><span><i>中</i>${referenceLink('class',b.mid[0],b.mid[0])}</span><span><i>上</i>${referenceLink('class',b.upper[0],b.upper[0])}</span></span>`}
function equipmentMapTerms(e){const pins=mapLoaded?PINS:CATALOG.mapTerms;return [...new Set([...e.sourcesList.map(s=>s.place),...e.materials.flatMap(m=>[m[0],m[3]])].filter(Boolean))].filter(t=>pins.some(p=>mapMatches(p,zh(t))))}

function equipmentInheritancePanel(){const a=CATALOG.equipmentInheritance;return `<section class="inheritance-panel"><h2>装备继承 · 可以汇集各路线</h2><p><b>${esc(a.summary)}</b></p><div class="inheritance-steps">${a.steps.map((step,i)=>`<article><span>${i+1}</span><div><h3>${esc(step.name)}</h3><p>${esc(step.text)}</p></div></article>`).join('')}</div><p class="muted">${esc(a.caution)}</p></section>`}

// Shared identity cell: recruit, cross-route planning and character-based arena tables.
function tableCharacter(c,{subtitle=c.role,recruit=false,tone='',showRating=true,extra=''}={}){return `<button class="table-character ${tone}" data-char="${c.id}" ${recruit?`data-recruit-char="${c.id}"`:''} aria-label="查看${esc(c.cn)}培养详情">${showRating?ratingBadge(c,false,true):''}${portrait(c)}<span class="table-character-copy"><b>${esc(c.cn)} ${isPreferred(c)?'<i aria-label="偏好角色">★</i>':''}</b>${subtitle?`<small ${subtitle===c.role?'data-skill-images="off"':''}>${esc(subtitle)}${extra}</small>`:''}</span></button>`}

let inlineSkillIndex;
function skillImageIndex(){if(inlineSkillIndex)return inlineSkillIndex;const index={...CATALOG.abilityIcons};for(const [n,file]of Object.entries(SKILL_ICON_FILES))index[n]={src:`assets/skills/${file}.webp`,kind:'技能类别'};for(const cl of DB.classes){if(!cl.col_37||index[cl.col_37])continue;const skill=(cl.allowedSkills||[]).find(n=>SKILL_ICON_FILES[n]);if(skill)index[cl.col_37]={src:`assets/skills/${SKILL_ICON_FILES[skill]}.webp`,kind:'职业熟练技能'};}return inlineSkillIndex=Object.fromEntries(Object.entries(index).map(([name,item])=>[esc(name),item]));}
function decorateSkillHTML(html){const index=skillImageIndex(),aliases={剑:'剑术',枪:'枪术',斧:'斧术',弓:'弓术',格:'格斗术',格斗:'格斗术',拳:'格斗术',黑魔:'黑魔术',白魔:'白魔术',马:'马术',飞行:'飞行术',重装:'重装术',步兵:'步兵术',指挥:'指挥术'},equipmentNames=new Set(EQUIPMENT.map(e=>esc(e.name))),names=[...new Set([...Object.keys(index),...equipmentNames])].filter(n=>n.length>1).sort((a,b)=>b.length-a.length),pattern=new RegExp(names.map(n=>n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+'|(?:'+Object.keys(aliases).sort((a,b)=>b.length-a.length).join('|')+')(?=\\s*[EDCBAS](?:[+]?)(?:[^a-zA-Z]|$))','g'),stack=[];return html.split(/(<[^>]+>)/g).map(part=>{if(part.startsWith('<')){const close=part.match(/^<\/(\w+)/),open=part.match(/^<(\w+)/);if(close){const i=stack.map(x=>x.tag.toLowerCase()).lastIndexOf(close[1].toLowerCase());if(i>=0)stack.splice(i);}else if(open&&!/\/\s*>$/.test(part)&&!/^(img|input|br|hr|meta|link|source|wbr)$/i.test(open[1])){const skip=stack.some(x=>x.skip)||/^(script|style|svg|option|textarea)$/i.test(open[1])||/data-skill-images="off"/.test(part)||/class="[^"]*(?:affinity-item|skill-inline|inline-entity-link)/.test(part);stack.push({tag:open[1],skip,card:/class="[^"]*\b(?:char-card|detail-skill|skill-growth)\b/.test(part)});}return part;}if(stack.some(x=>x.skip))return part;return part.replace(pattern,name=>{if(equipmentNames.has(name))return name;const item=index[name]||index[aliases[name]];if(item.src.startsWith('portraits/')&&stack.some(x=>x.card))return name;return `<span class="skill-inline"><img src="${item.src}" width="18" height="18" alt="" aria-hidden="true" loading="lazy" decoding="async" title="${esc(item.kind)}"><span>${name}</span></span>`;});}).join('');}


function questCard(e){return `<article class="quest-card ${e.type==='spectate'?'spectate-event':''}"><div>${tag('第'+e.chapter+'章')}${tag(e.type==='spectate'?'观战':'外传',e.type==='spectate'?'key':'')}${e.type==='spectate'?tag(e.precision):''}<h3>${e.name}</h3></div><div class="quest-dates"><span><small>${e.type==='spectate'?'观战日期':'受理期'}</small><b>${esc(e.schedule||e.start.replace('1449/',''))}${e.start!==e.end?' – '+e.end.replace('1449/',''):''}</b></span><span><small>${e.type==='spectate'?'观战时间':'完成期限'}</small><b>${e.time||e.deadline?.replace('1449/','')||'未独立记载'}</b></span></div><p>${esc([e.place,e.action].filter(Boolean).join(' · '))}</p><p>${esc(e.benefit)}</p>${link(e.source,'期限依据')}</article>`;}

function arenaObservationCalendar(){const rs=Object.keys(routes).filter(r=>r!=='救世篇'),active=arenaViewState['observation']||rs[0];return `<section class="arena-observation"><h2>斗技场观战 · 各路线记录</h2><p class="muted">${esc(CATALOG.arenaCalendar.note)}</p><div data-view-group="observation" data-view-kind="arena"><div class="view-tabs" role="tablist">${rs.map(r=>`<button role="tab" data-view-tab="${r}" aria-selected="${active===r}" tabindex="${active===r?0:-1}" class="${active===r?'active':''}">${routes[r]} <span>${ROUTE_EVENTS.filter(e=>e.type==='spectate'&&e.route===r).length}</span></button>`).join('')}</div>${rs.map(r=>`<div data-view-panel="${r}" ${active===r?'':'hidden'}>${chapterCalendar(ROUTE_EVENTS.filter(e=>e.type==='spectate'&&e.route===r),r,'watch-'+r,false)}</div>`).join('')}</div></section>`;}

// Character skills grow with level: the personal skill is held from the start, level skills join at fixed levels.
const skillGrowthCache=new Map();
function skillGrowth(c){if(skillGrowthCache.has(c.id))return skillGrowthCache.get(c.id);const personal=CATALOG.abilities.find(a=>a.type==='个人技能'&&a.name===c.personalSkill),levels=[],blaze=[];for(const a of CATALOG.abilities)for(const b of a.acquisition){if(b.characterId!==c.id)continue;const row={name:a.name,id:a.id,level:Number.isFinite(b.level)&&b.level>0?b.level:null,effect:b.description||a.descriptions[0]?.text||''};if(a.type==='特技'&&b.method==='等级／条件'&&!b.skill&&!levels.some(r=>r.name===a.name)&&(row.level||b.uncertain))levels.push({...row,condition:b.condition&&!/^角色专属的 Lv特技/.test(b.condition)?b.condition:''});if(a.type==='战技'&&b.weapon==='圣焰'&&!blaze.some(r=>r.name===a.name))blaze.push({...row,unlock:b.condition||'',might:b.parameters?.might||'',cost:b.parameters?.cost||''});}levels.sort((x,y)=>(x.level??999)-(y.level??999)||x.name.localeCompare(y.name,'zh'));for(const r of levels){const base=skillUpgradeTier(r.name)>0&&levels.find(x=>skillUpgradeKey(x.name)===skillUpgradeKey(r.name)&&skillUpgradeTier(x.name)<skillUpgradeTier(r.name)&&x.level&&x.level<r.level);if(base)r.upgradeOf=base.name;}const order=r=>r.level?100+r.level:/加入|序幕|第三部/.test(r.unlock)?0:(r.unlock.match(/第(\d+)章/)?.[1]*1||0)+(/剧情/.test(r.unlock)?0:300);blaze.sort((x,y)=>order(x)-order(y));const out={personal:{name:c.personalSkill,effect:c.personalSkillEffect,id:personal?.id},levels,blaze};skillGrowthCache.set(c.id,out);return out}
function skillGrowthLevel(level){return level==null?'等级待核实':level<=1?'初始':'Lv.'+level}
function skillGrowthName(s){return s.id?`<button class="skill-growth-name" data-reference-type="ability" data-reference-id="${escapeAttr(s.id)}">${esc(s.name)}</button>`:`<b class="skill-growth-name">${esc(s.name)}</b>`}
function cardSkillGrowth(c){const g=skillGrowth(c),known=g.levels.filter(s=>s.level);return `<div class="card-skill"><b>${esc(g.personal.name)}</b><p>${emphasis(g.personal.effect)}</p>${known.length?`<ol class="skill-ladder" aria-label="${escapeAttr(c.cn)}的等级习得技能">${known.map(s=>`<li><span>${skillGrowthLevel(s.level)}</span>${skillGrowthName(s)}</li>`).join('')}</ol>`:''}</div>`}
function skillGrowthStep(when,s,extra=''){return `<li class="skill-item"><div class="skill-item-head">${skillGrowthName(s)}<span class="skill-when${/^Lv\./.test(when)?' is-level':''}">${esc(when)}</span></div><p>${emphasis(s.effect||'效果未收录')}</p>${extra}${s.upgradeOf?`<small class="skill-growth-upgrade">强化「${esc(s.upgradeOf)}」</small>`:''}${s.condition?`<small class="skill-growth-note">${esc(s.condition)}</small>`:''}</li>`}
function personalSkillPanel(c){const g=skillGrowth(c),source=(LEARNING?.[c.id]?.combatArts||[]).map(a=>a.name),blazeArts=source.length?[...g.blaze].sort((x,y)=>source.indexOf(x.name)-source.indexOf(y.name)):g.blaze,blazeStage=s=>s.level?'Lv.'+s.level:/加入|序幕|第三部/.test(s.unlock)?'初始':/兴行/.test(s.unlock)?'兴行':/剧情/.test(s.unlock)?'剧情':'条件',blazeMeta=s=>{const m=[s.cost&&'消耗 '+s.cost,s.might&&'威力 '+s.might].filter(Boolean);return m.length?`<small class="skill-growth-meta">${esc(m.join(' · '))}</small>`:''},group=(label,items,upgrades=0)=>items.length?`<div class="skill-group"><h3 class="skill-group-label">${label}<small>${items.length} 项${upgrades?` · 含强化 ${upgrades}`:''}</small></h3><ol class="skill-list">${items.join('')}</ol></div>`:'';return `<section class="skill-growth" aria-labelledby="skill-growth-${c.id}"><div class="skill-growth-head"><h2 id="skill-growth-${c.id}">角色技能</h2></div><div class="skill-group skill-group-personal"><h3 class="skill-group-label">个人技能</h3><div class="skill-signature">${skillGrowthName(g.personal)}<p>${emphasis(g.personal.effect||'效果未收录')}</p></div></div>${group('等级习得',g.levels.map(s=>skillGrowthStep(skillGrowthLevel(s.level),s)),g.levels.filter(s=>s.upgradeOf).length)}${group('炽焰技艺',blazeArts.map(s=>skillGrowthStep(blazeStage(s),{...s,condition:s.level||/加入时/.test(s.unlock)?'':s.unlock},blazeMeta(s))))}</section>`}

