function arenaRecommendedSubtitle(c){return skillTargets(c).map(g=>g.skill+' '+g.rank).join(' · ')||'暂无重点训练需求'}

const chapterCalendarState=new Map(),chapterCalendarEvents=new Map();
function calendarDate(value){const m=String(value||'').match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!m)return null;const d=new Date(Date.UTC(+m[1],+m[2]-1,+m[3]));return d.getUTCFullYear()===+m[1]&&d.getUTCMonth()===+m[2]-1&&d.getUTCDate()===+m[3]?d:null}
function calendarStamp(d){return `${d.getUTCFullYear()}/${String(d.getUTCMonth()+1).padStart(2,'0')}/${String(d.getUTCDate()).padStart(2,'0')}`}
function calendarShort(value){const d=calendarDate(value);return d?`${d.getUTCMonth()+1}/${d.getUTCDate()}`:''}
function calendarEntries(events,r,withMilestones){const entries=events.map(e=>({...e,key:'event-'+ROUTE_EVENTS.indexOf(e),kind:e.type==='spectate'?'spectate':'quest'}));if(withMilestones){const titles=CATALOG.chapterCalendar?.chapterTitles?.[r]||{};for(const m of CATALOG.chapterCalendar.mainline[r]||[]){const chTitle=m.title||titles[String(m.chapter)]||'';const base={...m,title:chTitle,action:m.note.split(' 开始日期按')[0],name:m.name.replace('主线准备','主线'),benefit:'自由行动 '+m.turns+'回合；结束后按主线指引进入战斗。',related:[]};entries.push({...base,key:'main-'+r+'-'+m.chapter,kind:'main'})}}return entries}
function calendarChapterOverview(r,scope,state){
 const list=CATALOG.chapterCalendar?.mainline?.[r]||[];
 if(!list.length)return '';
 const titles=CATALOG.chapterCalendar?.chapterTitles?.[r]||{};
 const firstCh=list[0].chapter;
 const early=[];
 for(let ch=1;ch<firstCh;ch++)early.push(`<span class="cal-ch-early" title="序盘剧情连战章节（无自由行动日历）"><b>第${ch}章</b><small>${esc(titles[String(ch)]||'剧情战斗')}</small><em>剧情战</em></span>`);
 const free=list.map(m=>{
  const mKey=calendarStamp(calendarDate(m.start)).slice(0,7);
  const on=state.month===mKey;
  const chTitle=m.title||titles[String(m.chapter)]||'';
  return `<button type="button" class="cal-ch-pill${on?' active':''}" data-calendar-scope="${scope}" data-calendar-month="${mKey}" title="第${m.chapter}章 ${esc(chTitle)}：${calendarShort(m.start)}—${calendarShort(m.end)}（自由行动 ${m.turns} 回合）"><b>第${m.chapter}章${chTitle?' · '+esc(chTitle):''}</b><small>${calendarShort(m.start)}—${calendarShort(m.end)} · <i>${m.turns}回合</i></small></button>`;
 }).join('');
 return `<div class="calendar-chapter-strip" aria-label="全章节时间轴">${early.join('')}${free}</div>`;
}
function calendarIntersects(e,start,end){const a=calendarDate(e.start),b=calendarDate(e.end)||a,deadline=calendarDate(e.deadline);return !!(a&&a<=end&&b>=start||deadline&&deadline>=start&&deadline<=end)}
function chapterCalendar(events,r,scope,withMilestones=true){chapterCalendarEvents.set(scope,{events,r,withMilestones});const entries=calendarEntries(events,r,withMilestones),dates=entries.flatMap(e=>[e.start,e.end,e.deadline]).map(calendarDate).filter(Boolean).sort((a,b)=>a-b),months=[];if(dates.length){const end=dates.at(-1),d=new Date(Date.UTC(dates[0].getUTCFullYear(),dates[0].getUTCMonth(),1));while(d<=end&&months.length<24){months.push(new Date(d));d.setUTCMonth(d.getUTCMonth()+1)}}const state=chapterCalendarState.get(scope)||{month:months.length?calendarStamp(months[0]).slice(0,7):'',selected:''};if(!months.some(d=>calendarStamp(d).slice(0,7)===state.month))state.month=months.length?calendarStamp(months[0]).slice(0,7):'';chapterCalendarState.set(scope,state);const month=calendarDate(state.month+'/01'),end=month?new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)):null,active=month?entries.filter(e=>calendarIntersects(e,month,end)):[],selected=entries.find(e=>e.key===state.selected),undated=entries.filter(e=>!calendarDate(e.start)),agenda=active.filter(e=>e.kind!=='main');return `<div class="chapter-calendar month-calendar" id="calendar-${scope}">${withMilestones?calendarChapterOverview(r,scope,state):''}<div class="calendar-chapters calendar-month-tabs" role="tablist" aria-label="月份日历">${months.map(d=>{const key=calendarStamp(d).slice(0,7),end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0));return `<button role="tab" id="month-${scope}-${key}" aria-controls="month-panel-${scope}" tabindex="${state.month===key?0:-1}" data-calendar-scope="${scope}" data-calendar-month="${key}" aria-selected="${state.month===key}" class="${state.month===key?'active':''}"><span>${d.getUTCMonth()+1}月</span><small>${entries.filter(e=>calendarIntersects(e,d,end)).length}</small></button>`}).join('')}</div><div class="calendar-heading"><h3>${month?month.getUTCFullYear()+'年 '+(month.getUTCMonth()+1)+'月':'日期待核实'}<small>${active.length}项已收录重点</small></h3><div class="calendar-key"><span class="mainline">主线自由行动</span><span class="spectate">观战日期</span><span class="quest">外传区间</span><span class="deadline">截止 · 与外传同色</span></div></div><div class="calendar-months" role="tabpanel" id="month-panel-${scope}" aria-labelledby="month-${scope}-${state.month}" tabindex="0">${month?calendarMonth(month,active,scope,state.selected):'<div class="calendar-empty">本路线暂无已核实日期，记录见下方。</div>'}</div><div class="calendar-agenda">${agenda.map(e=>calendarEventButton(e,scope,e.name+' · '+calendarShort(e.start)+(e.kind==='quest'&&e.start!==e.end?'—'+calendarShort(e.end):''),e.kind,state.selected)).join('')}</div>${undated.length?`<div class="calendar-undated"><b>章首／自由行动触发观战</b>${undated.map(e=>calendarEventButton(e,scope,'第'+e.chapter+'章 · '+e.name+(e.schedule?'（'+e.schedule+'）':''),'undated',state.selected)).join('')}</div>`:''}${selected?calendarEventDetail(selected):''}<p class="calendar-footnote">${withMilestones&&!CATALOG.chapterCalendar.mainline[r]?.length?'本路线主线起止日期尚待核对，目前显示已收录任务与观战。 ':''}${esc(CATALOG.chapterCalendar.note)}</p></div>`}
const CALENDAR_QUEST_PALETTE=['#b28600','#9f1853','#8a3800','#72751b','#7d3f70','#cc3f25','#8c7057','#c76b08','#a2191f','#a77728','#ae5571','#63513b'];
let calendarQuestColorCache=null;
function calendarQuestColors(){if(calendarQuestColorCache)return calendarQuestColorCache;const quests=ROUTE_EVENTS.filter(e=>e.type!=='spectate'),names=[...new Set(quests.map(e=>e.name))].sort(),neighbors=new Map(names.map(n=>[n,new Set()]));for(const r of new Set(quests.map(e=>e.route))){const group=[...new Set(quests.filter(e=>e.route===r).map(e=>e.name))];for(const n of group)for(const other of group)if(n!==other)neighbors.get(n).add(other)}const result={};for(const name of names.sort((a,b)=>neighbors.get(b).size-neighbors.get(a).size||a.localeCompare(b,'zh-CN'))){const used=new Set([...neighbors.get(name)].map(n=>result[n]));const candidates=CALENDAR_QUEST_PALETTE.filter(c=>!used.has(c)),distance=(a,b)=>{const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));const x=rgb(a),y=rgb(b);return Math.hypot(...x.map((v,i)=>v-y[i]))},score=c=>used.size?Math.min(...[...used].filter(Boolean).map(other=>distance(c,other))):0;result[name]=candidates.sort((a,b)=>score(b)-score(a))[0]||CALENDAR_QUEST_PALETTE[0]}return calendarQuestColorCache=result}
function calendarEventStyle(e){return e.kind==='quest'?`--event-color:${calendarQuestColors()[e.name]};--event-bg:color-mix(in srgb,var(--event-color) 26%,var(--card));--event-ink:color-mix(in srgb,var(--event-color) 65%,var(--ink))`:''}
function calendarEventButton(e,scope,label,kind,selected){return `<button style="${calendarEventStyle(e)}" class="calendar-event ${kind==='main'?'mainline':kind} ${e.key===selected?'selected':''}" data-calendar-scope="${scope}" data-calendar-event="${esc(e.key)}" aria-expanded="${e.key===selected}" aria-label="${esc(e.name+(e.kind==='main'?' · '+calendarShort(e.start)+'—'+calendarShort(e.end):''))}" title="${esc(e.name+' · '+(calendarShort(e.start)||e.schedule||'日期待核实')+' · '+(e.time||'') )}">${esc(label)}</button>`}
function calendarMonth(month,entries,scope,selected){const year=month.getUTCFullYear(),m=month.getUTCMonth(),last=new Date(Date.UTC(year,m+1,0)).getUTCDate(),anchor=calendarDate(CATALOG.chapterCalendar.weekdayAnchor.date),offset=((Math.round((month-anchor)/86400000)+CATALOG.chapterCalendar.weekdayAnchor.weekday)%7+7)%7,weeks=Math.ceil((offset+last)/7);let shownMain=new Set();return `<section class="calendar-month"><h4>${year}年 <strong>${m+1}月</strong></h4><div class="calendar-weekdays">${['一','二','三','四','五','六','日'].map(n=>`<span>${n}</span>`).join('')}</div>${Array.from({length:weeks},(_,w)=>{const days=Array.from({length:7},(_,i)=>w*7+i-offset+1),rows=[];for(const e of entries){const start=calendarDate(e.start),end=calendarDate(e.end)||start;const span=days.map((day,i)=>({day,i,date:new Date(Date.UTC(year,m,day))})).filter(x=>x.day>=1&&x.day<=last&&x.date>=start&&x.date<=end);if(span.length){let label=e.name;if(e.kind==='spectate')label='观战 '+(e.time||'时间待核实');else if(e.kind==='main'){const firstInMonth=!shownMain.has(e.key);shownMain.add(e.key);label=firstInMonth?(e.name+' · '+calendarShort(e.start)+'—'+calendarShort(e.end)):(e.name+(e.title?' · '+e.title:'')+'（续）');}rows.push(`<div class="calendar-band-row"><div style="grid-column:${span[0].i+1} / span ${span.length}">${calendarEventButton(e,scope,label,e.kind,selected)}</div></div>`)}const deadline=calendarDate(e.deadline);if(deadline&&deadline.getUTCMonth()===m&&deadline.getUTCFullYear()===year){const i=days.indexOf(deadline.getUTCDate());if(i>=0)rows.push(`<div class="calendar-band-row"><div style="grid-column:${i+1}">${calendarEventButton(e,scope,e.name+' · 截止','deadline',selected)}</div></div>`)}}return `<div class="calendar-week"><div class="calendar-days">${days.map(day=>`<span class="${day<1||day>last?'outside':''}">${day<1||day>last?'':day}</span>`).join('')}</div><div class="calendar-bands">${rows.join('')}</div></div>`}).join('')}</section>`}
function calendarEventDetail(e){return `<section style="${calendarEventStyle(e)}" class="calendar-event-detail ${e.kind==='main'?'mainline':e.kind}"><div><h3>${esc(e.name)}</h3><small class="heading-meta">第${e.chapter}章 · ${e.kind==='spectate'?'斗技场观战':e.kind==='milestone'||e.kind==='main'?'主线准备':'任务详情'}</small></div><dl><div><dt>${e.kind==='quest'?'受理区间':e.kind==='main'?'准备区间':'日期'}</dt><dd>${calendarShort(e.start)?calendarShort(e.start)+(e.start!==e.end?' — '+calendarShort(e.end):''):esc(e.schedule||'日期待核实')}</dd></div><div><dt>${e.kind==='quest'?'完成期限':'时间'}</dt><dd>${esc(e.kind==='quest'?calendarShort(e.deadline)||'未独立记载':e.time||'时段待核实')}</dd></div></dl><p>${esc([e.place,e.action].filter(Boolean).join(' · '))}</p><p>${esc(e.benefit||'')}</p>${e.related?.length?`<div class="calendar-related">${e.related.map(id=>DB.characters.find(c=>c.id===id)).filter(Boolean).map(c=>tableCharacter(c,{showRating:false})).join('')}</div>`:''}</section>`}
function calendarClick(e){const b=e.target.closest('[data-calendar-scope]');if(!b)return false;const scope=b.dataset.calendarScope,config=chapterCalendarEvents.get(scope);if(!config)return false;const state=chapterCalendarState.get(scope);if(b.dataset.calendarMonth){state.month=b.dataset.calendarMonth;state.selected=''}else if(b.dataset.calendarEvent)state.selected=state.selected===b.dataset.calendarEvent?'':b.dataset.calendarEvent;const host=document.getElementById('calendar-'+scope);if(host){const html=viewHTML(chapterCalendar(config.events,config.r,scope,config.withMilestones));host.outerHTML=html;if(b.dataset.calendarMonth)document.getElementById("month-"+scope+"-"+state.month)?.focus({preventScroll:true});}return true}

