function equipmentSourcePreview(e){const kinds=[...new Set(e.sourcesList.map(source=>source.kind||equipmentSourceModel(e,source).kind))];const forgeMats=(e.forgeMaterials||[]).map(m=>`${m.name}×${m.qty}`).join(' + ');return `<div class="equipment-source-preview source-tags-preview" data-skill-images="off"><div><small>获取途径</small><div class="source-preview-tags">${kinds.map(kind=>tag(kind,'source-kind')).join('')}${e.maxForge?`<span class="tag forge-badge" title="${esc(e.forgeSummary||'可强化')}">锻造 ${esc(e.maxForge)}${forgeMats?' · '+esc(forgeMats):''}</span>`:''}</div></div><span class="source-total" title="数量来自各路线来源记录中的明确库存；实际可达范围以路线为准">${sourceQuantityLabel(e)}</span></div>`}
