function mapSuggestCurrent(){return guidePage()==='map'?$('#search'):$('[data-route-map-search]')}
function mapSuggestTerms(isRoute){const pool=isRoute?PINS.filter(p=>p.area===route):PINS,terms=new Map(),add=(term,kind,pin)=>{term=String(term||'').trim();if(!term)return;const k=kind+'|'+term,hit=terms.get(k)||{term,kind,pins:new Set(),first:pin};hit.pins.add(pin.name+'@'+pin.x+','+pin.y);terms.set(k,hit)};pool.forEach(p=>{add(p.name,MAP_GATHER_TYPES.includes(p.type)?'采集点':'地点',p);add(p.type,'类型',p);String(p.info||'').replace(/【[^】]*】/g,'；').split(/[、，,；;／\/\s]+/).forEach(x=>add(x.replace(/[（(].*$/,'').replace(/^[·・]+|[【】]/g,''),/店$/.test(x)?'店铺':'可获取',p))});return [...terms.values()]}
function mapSuggestList(q,isRoute){q=String(q||'').trim();if(!q||!mapLoaded)return [];const variants=materialQueryVariants(q),rank={'采集点':0,'可获取':1,'店铺':2,'地点':3,'类型':4};return mapSuggestTerms(isRoute).map(x=>{const pos=Math.min(...variants.map(v=>{const i=x.term.indexOf(v);return i<0?99:i}));return {...x,pos}}).filter(x=>x.pos<99&&x.term!==q).sort((a,b)=>(a.pos>0)-(b.pos>0)||b.pins.size-a.pins.size||rank[a.kind]-rank[b.kind]||a.term.length-b.term.length).slice(0,8)}
function mapSuggestMark(term,q){const i=term.indexOf(q);return i<0?esc(term):esc(term.slice(0,i))+'<mark>'+esc(q)+'</mark>'+esc(term.slice(i+q.length))}
function hideMapSuggest(){mapSuggestItems=[];mapSuggestActive=-1;if(mapSuggestBox)mapSuggestBox.hidden=true;mapSuggestCurrent()?.setAttribute('aria-expanded','false')}
function placeMapSuggest(input){if(!mapSuggestBox||mapSuggestBox.hidden||!input)return;const r=(input.closest('.search')||input).getBoundingClientRect();Object.assign(mapSuggestBox.style,{left:r.left+'px',top:(r.bottom+6)+'px',width:Math.max(r.width,240)+'px'})}
function showMapSuggest(input){const q=input.value.trim();mapSuggestItems=mapSuggestList(q,input.matches('[data-route-map-search]'));mapSuggestActive=-1;if(!mapSuggestItems.length)return hideMapSuggest();if(!mapSuggestBox){mapSuggestBox=document.createElement('ul');mapSuggestBox.id='map-suggest';mapSuggestBox.className='map-suggest';mapSuggestBox.setAttribute('role','listbox');mapSuggestBox.setAttribute('aria-label','搜索联想');document.body.append(mapSuggestBox)}mapSuggestBox.innerHTML=mapSuggestItems.map((x,i)=>`<li role="option" id="map-suggest-${i}" data-map-suggest="${i}" aria-selected="false"><span>${mapSuggestMark(x.term,q)}</span><small>${esc(x.kind)} · ${x.pins.size}处</small></li>`).join('');mapSuggestBox.hidden=false;input.setAttribute('aria-expanded','true');input.setAttribute('aria-controls','map-suggest');input.setAttribute('aria-autocomplete','list');placeMapSuggest(input)}
function moveMapSuggest(step){if(!mapSuggestItems.length)return;mapSuggestActive=(mapSuggestActive+step+mapSuggestItems.length)%mapSuggestItems.length;mapSuggestBox.querySelectorAll('[data-map-suggest]').forEach((li,i)=>{li.classList.toggle('active',i===mapSuggestActive);li.setAttribute('aria-selected',i===mapSuggestActive)});mapSuggestCurrent()?.setAttribute('aria-activedescendant','map-suggest-'+mapSuggestActive)}
function pickMapSuggest(i){const x=mapSuggestItems[i],input=mapSuggestCurrent();if(!x||!input)return;const isRoute=input.matches('[data-route-map-search]');hideMapSuggest();clearTimeout(searchTimer);if(isRoute)routeMapQueries[route]=x.term;else query=x.term;mapSuggestHold=true;render();const next=mapSuggestCurrent();next?.focus();mapSuggestHold=false;next?.setSelectionRange(x.term.length,x.term.length);if(!isRoute&&(x.kind==='地点'||x.kind==='采集点')&&x.pins.size===1){selectMapPin(x.first.id);focusMapPin(x.first.id)}}
const commitSearchBase=commitSearch;commitSearch=function(input){commitSearchBase(input);if(mapSuggestInput(input)&&typeof input.closest==='function')showMapSuggest(input)};
document.addEventListener('focusin',e=>{if(mapSuggestHold)return;if(mapSuggestInput(e.target)&&e.target.value.trim())showMapSuggest(e.target);else if(!e.target.closest?.('#map-suggest'))hideMapSuggest()});
document.addEventListener('focusout',e=>{if(mapSuggestInput(e.target))setTimeout(()=>{if(!mapSuggestInput(document.activeElement))hideMapSuggest()},150)});
document.addEventListener('keydown',e=>{if(!mapSuggestInput(e.target)||e.isComposing||!mapSuggestItems.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();moveMapSuggest(e.key==='ArrowDown'?1:-1)}else if(e.key==='Enter'&&mapSuggestActive>=0){e.preventDefault();e.stopImmediatePropagation();pickMapSuggest(mapSuggestActive)}else if(e.key==='Escape'){e.stopImmediatePropagation();hideMapSuggest()}},true);
document.addEventListener('pointerdown',e=>{const li=e.target.closest?.('[data-map-suggest]');if(li){e.preventDefault();pickMapSuggest(Number(li.dataset.mapSuggest))}else if(mapSuggestBox&&!mapSuggestBox.hidden&&!mapSuggestInput(e.target))hideMapSuggest()},true);
window.addEventListener('hashchange',hideMapSuggest);
window.addEventListener('resize',()=>placeMapSuggest(mapSuggestCurrent()));
document.addEventListener('scroll',()=>placeMapSuggest(mapSuggestCurrent()),true);
// 统一搜索框：清空按钮、Esc 清空、「/」聚焦当前页搜索
function clearSearchInput(input){if(!input)return;if(input.matches('[data-wb-character-search]')){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();return}if(typeof hideMapSuggest==='function')hideMapSuggest();clearTimeout(searchTimer);if(input.matches('[data-route-map-search]'))routeMapQueries[route]='';else query='';render();const next=input.matches('[data-route-map-search]')?$('[data-route-map-search]'):$('#search');next?.focus()}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-search-clear]');if(b){e.preventDefault();clearSearchInput(b.closest('.search')?.querySelector('input'))}});
document.addEventListener('keydown',e=>{const t=e.target;if(e.key==='Escape'&&t.matches?.('.search input,#anna-ask-input')&&t.value&&!(typeof mapSuggestItems!=='undefined'&&mapSuggestItems.length)){e.preventDefault();if(t.id==='anna-ask-input'){t.value='';t.dispatchEvent(new Event('input',{bubbles:true}));}else clearSearchInput(t);return}if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!e.isComposing&&!t.closest?.('input,textarea,select,[contenteditable="true"],dialog[open]')){if($('#annaSearch')?.open)return;const s=$('#search')||$('#anna-ask-input');if(s){e.preventDefault();s.focus();s.select()}else if(typeof openAnnaSearch==='function'){e.preventDefault();openAnnaSearch()}}});
let characterTocFrame=0;function updateCharacterToc(){characterTocFrame=0;const page=document.getElementById?.('characterPage'),toc=page?.querySelector('.character-toc');if(!toc)return;const heads=[...page.querySelectorAll('h2[id]')];let current=heads[0]?.id;for(const h of heads){if(h.getBoundingClientRect().top<Math.min(260,(window.innerHeight||800)*.35))current=h.id;else break}for(const b of toc.querySelectorAll('[data-scroll]')){const on=b.dataset.scroll===current;b.classList.toggle('current',on);if(on){b.setAttribute('aria-current','location');if(toc.scrollWidth>toc.clientWidth+4){const l=b.offsetLeft-toc.clientWidth/2+b.offsetWidth/2;toc.scrollTo({left:l,behavior:'smooth'})}}else b.removeAttribute('aria-current')}}
window.addEventListener('scroll',()=>{if(!characterTocFrame&&characterOpen())characterTocFrame=requestAnimationFrame(updateCharacterToc)},{passive:true});

// 材料反查：由装备兑换来源与铁匠铺锻造配方反推「这个材料能换什么 / 能锻造什么」，并联动采集地点与地图。
let materialExchangeCache=null,materialKindFilter='all';
function materialName(n){return (CATALOG.materialAliases||{})[n]||n}
function materialBadge(name,kind='exchange'){
 const isForge=kind==='forge'||/石|钢|晶|矿|金属/.test(name);
 const src=isForge?'assets/equipment/shield.webp':'assets/equipment/ring.webp';
 return `<span class="item-badge ${isForge?'badge-forge':'badge-material'}" aria-hidden="true"><img src="${src}" width="24" height="24" alt="" loading="lazy" decoding="async"></span>`;
}
function materialExchangeIndex(){
 if(materialExchangeCache)return materialExchangeCache;
 const rows=new Map();
 const ensure=name=>{
  if(!rows.has(name))rows.set(name,{name,kind:'商会兑换',aliases:new Set(),where:new Set(),uses:new Map(),forgeUses:new Map(),desc:''});
  return rows.get(name);
 };
 for(const e of EQUIPMENT)for(const s of e.sourcesList||[]){
  if(!/兑换/.test(s.kind||''))continue;
  const mats=materialsForSource(e,s);if(!mats.length)continue;
  const recipe=mats.map(m=>materialName(m[0])+' × '+m[2]).join(' + ');
  for(const m of mats){
   const name=materialName(m[0]),row=ensure(name);
   if(m[0]!==name)row.aliases.add(m[0]);
   String(m[3]||'').split(/\s*[\/／、]\s*/).filter(Boolean).forEach(w=>row.where.add(w));
   const key=e.id+'|'+(s.place||'');
   if(!row.uses.has(key))row.uses.set(key,{e,place:s.place||'',qty:Number(m[2])||0,recipe,mode:'exchange'});
  }
 }
 for(const [k,v] of Object.entries(CATALOG.materialAliases||{}))rows.get(v)?.aliases.add(k);
 const fgMeta=new Map((CATALOG.forgingMaterials||[]).map(m=>[m.name,m]));
 for(const e of EQUIPMENT){
  if(!e.forgeMaterials?.length)continue;
  const stepText=(e.forgeSteps||[]).map(st=>`${st.step}(${(st.materials||[]).map(x=>x.name+'×'+x.qty).join('+')})`).join(' → ');
  for(const fm of e.forgeMaterials){
   const name=materialName(fm.name),row=ensure(name);
   if(!row.uses.size)row.kind='武器锻造';else row.kind='兑换与锻造';
   const meta=fgMeta.get(name);
   if(meta){
    if(meta.description)row.desc=meta.description;
    (meta.places||[]).forEach(w=>row.where.add(w));
    (meta.boxes||[]).forEach(b=>row.where.add('开箱：'+b));
   }
   const recipe=`强化至 ${e.maxForge||'+3'} 共需 ${name} × ${fm.qty}${e.forgeGold?`（${e.forgeGold}G）`:''}`;
   row.forgeUses.set(e.id,{e,place:'铁匠铺锻造',qty:Number(fm.qty)||0,recipe,stepText,mode:'forge'});
  }
 }
 materialExchangeCache=[...rows.values()].map(r=>{
  const exUses=[...r.uses.values()],fgUses=[...r.forgeUses.values()];
  return {...r,aliases:[...r.aliases],where:[...r.where],uses:exUses,forgeUses:fgUses,allUses:[...exUses,...fgUses]};
 }).sort((a,b)=>new Set(b.allUses.map(u=>u.e.id)).size-new Set(a.allUses.map(u=>u.e.id)).size||a.name.localeCompare(b.name,'zh'));
 return materialExchangeCache;
}
function materialMatches(row,q){if(!q)return true;const terms=materialQueryVariants(q);return terms.some(t=>[row.name,row.kind,...row.aliases,...row.where,...row.allUses.flatMap(u=>[u.e.name,u.place])].some(x=>x&&x.includes(t)))}
function materialRow(row){
 const allUses=row.allUses||row.uses,gear=[...new Map(allUses.map(u=>[u.e.id,u.e])).values()],own=materialOwned(row.name),isForge=row.kind.includes('锻造');
 return `<article class="material-row" id="material-${escapeAttr(row.name)}"><div class="material-row-name"><div class="material-name-head">${materialBadge(row.name,isForge?'forge':'exchange')}<div><b>${esc(row.name)}</b><small class="material-kind-tag">${esc(row.kind)}</small></div></div>${row.aliases.length?`<small>又译 ${esc(row.aliases.join(' / '))}</small>`:''}<span class="material-row-count">${row.uses.length?`可换 <b>${new Set(row.uses.map(u=>u.e.id)).size}</b> 件`:''}${row.uses.length&&row.forgeUses?.length?' · ':''}${row.forgeUses?.length?`可锻造 <b>${row.forgeUses.length}</b> 把`:''}${own?` · 已有 ${own}`:''}</span></div><ul class="material-uses">${allUses.map(u=>`<li><button type="button" class="material-gear ${u.mode==='forge'?'is-forge-use':''}" data-reference-type="equipment" data-reference-id="${u.e.id}" aria-haspopup="dialog" data-skill-images="off"><span class="material-gear-icon">${equipmentIcon(u.e)}</span><span><b>${esc(u.e.name)}${u.mode==='forge'&&u.e.maxForge?` <em>${esc(u.e.maxForge)}</em>`:''}</b><small>${esc(u.recipe)}${u.place?' · '+esc(u.place):''}</small></span></button></li>`).join('')}</ul><div class="material-where"><small>获取与采集地点</small><p>${row.where.length?esc(row.where.slice(0,8).join(' / ')):'<span class="muted">迷宫探索或任务获取</span>'}</p><button type="button" class="text-button" data-map="${escapeAttr(row.name)}">在地图上查看 ↗</button></div></article>`;
}
function materialRowsFor(gear){const ids=new Set(gear.map(e=>e.id)),filtered=gear.length<EQUIPMENT.length;return materialExchangeIndex().map(r=>{if(!filtered)return r;const uses=r.uses.filter(u=>ids.has(u.e.id)),forgeUses=(r.forgeUses||[]).filter(u=>ids.has(u.e.id));return {...r,uses,forgeUses,allUses:[...uses,...forgeUses]}}).filter(r=>r.allUses.length&&(materialKindFilter==='all'||(materialKindFilter==='exchange'?r.uses.length>0:r.forgeUses?.length>0))&&(materialMatches(r,query)||filtered)).sort((a,b)=>{const q=query&&materialQueryVariants(query),hit=r=>q&&[r.name,...r.aliases].some(n=>q.includes(n))?0:1;return hit(a)-hit(b)})}
function materialLookup(gear){const list=materialRowsFor(gear);return `<div class="segments material-kind-tabs" role="group" aria-label="材料用途筛选">${[['all','全部材料'],['exchange','商会兑换材料'],['forge','铁匠铺锻造石材']].map(([k,n])=>`<button type="button" data-mat-kind="${k}" class="${materialKindFilter===k?'active':''}">${n}</button>`).join('')}</div><div class="material-ledger">${list.map(materialRow).join('')||'<p class="muted">没有匹配的材料记录。</p>'}</div>`}
function equipmentViews(gearHTML,gear){const hit=query&&materialExchangeIndex().find(r=>[r.name,...r.aliases].some(n=>materialQueryVariants(query).includes(n)));return (hit?`<p class="material-hint">${esc(hit.name)}的关联装备 <button type="button" class="text-button" data-material-lookup>查看材料与配方 ↗</button></p>`:'')+equipmentTable(gear)}
function pinMaterialExchange(p){const text=`${p.name} ${p.info||''}`,rows=materialExchangeIndex().filter(r=>[r.name,...r.aliases].some(n=>text.includes(n)));if(!rows.length)return '';return `<h3>本地材料可兑换</h3><ul class="pin-material-exchange">${rows.map(r=>`<li><b>${esc(r.name)}</b><span>${[...new Map(r.uses.map(u=>[u.e.id,u.e])).values()].map(e=>`<button class="text-button" data-reference-type="equipment" data-reference-id="${e.id}">${esc(e.name)}</button>`).join('')}</span></li>`).join('')}</ul>`}
const SHOP_KIND_NAMES={item:'道具店',market:'市集',gift:'礼品店',weapon:'武器店',trader:'行商',guild:'公会',license:'许可证',secret:'秘密商店'};
function pinShops(p){if(!MAP_EXTRAS){loadMapExtras();return null}return MAP_EXTRAS.shops.filter(s=>s.place===p.id)}
function pinShopInventory(p){const shops=pinShops(p);if(!shops||!shops.length)return '';const gearByName=new Map(EQUIPMENT.map(e=>[e.name,e])),groups=new Map();for(const s of shops){const label=SHOP_KIND_NAMES[s.kind]||s.kind,g=groups.get(s.kind)||{label,names:new Set(),goods:new Map()};if(s.name!==label)g.names.add(s.name);for(const [name,price,stock] of s.goods){const key=name+'|'+price,row=g.goods.get(key)||{name,price,stocks:new Set()};row.stocks.add(stock);g.goods.set(key,row)}groups.set(s.kind,g)}return `<h3>店铺与商品</h3><div class="pin-shop-groups">${[...groups.values()].map(g=>`<section class="pin-shop-group"><h4>${esc(g.label)}${g.names.size?`<small>${[...g.names].map(esc).join('、')}</small>`:''}</h4><table class="pin-shop-table"><tbody>${[...g.goods.values()].map(r=>{const e=gearByName.get(r.name),stocks=[...r.stocks].filter(x=>x),stock=stocks.length?`库存 ${Math.min(...stocks)===Math.max(...stocks)?stocks[0]:Math.min(...stocks)+'~'+Math.max(...stocks)}`:'';return `<tr><td>${e?`<button class="text-button" data-reference-type="equipment" data-reference-id="${e.id}">${esc(r.name)}</button>`:esc(r.name)}</td><td>${r.price==null?'—':r.price+'G'}</td><td class="muted">${stock}</td></tr>`}).join('')}</tbody></table></section>`).join('')}</div>`}
function pinGatherSpots(p){if(!MAP_EXTRAS){loadMapExtras();return ''}const rows=MAP_EXTRAS.gather.filter(g=>g.place===p.id);if(!rows.length)return '';const groups=new Map();for(const r of rows){const g=groups.get(r.how)||new Set();g.add(r.item);groups.set(r.how,g)}return `<h3>采集与探索</h3><ul class="pin-material-exchange pin-gather-spots">${[...groups.entries()].map(([how,items])=>`<li><b>${esc(how)}</b><span>${[...items].map(esc).join('、')}</span></li>`).join('')}</ul>`}
{const basePinDetail=mapPinDetail;mapPinDetail=function(id){let html=basePinDetail(id);const p=PINS.find(x=>x.id===id);if(!p)return html;const extra=pinMaterialExchange(p)+pinShopInventory(p)+pinGatherSpots(p),shops=pinShops(p);if(shops&&shops.length)html=html.replace('<p class="muted">此点位的武器清单尚未逐店补全；可在装备页查询已核实来源。</p>','');if(!extra)return html;const at=html.lastIndexOf('<a class="map-pin-source"');return at>=0?html.slice(0,at)+extra+html.slice(at):html.replace(/<\/article>\s*$/,extra+'</article>')}}
document.addEventListener('click',e=>{
 const mk=e.target.closest?.('[data-mat-kind]');if(mk){materialKindFilter=mk.dataset.matKind;render();return}
 const fm=e.target.closest?.('[data-forge-mat]');if(fm){const name=fm.dataset.forgeMat;if($('#sourceDialog')?.open)$('#sourceDialog').close();query=name;materialKindFilter='all';location.hash='#materials';render();return}
 if(!e.target.closest?.('[data-material-lookup]'))return;location.hash='#materials';render()
});

// 礼物与喜好数据库：双向查看「礼物 → 喜爱角色」与「角色 → 偏好分类 & 喜爱礼物」。
let giftCategoryFilter='all',giftCharacterFilter='',giftViewMode='characters';
function giftPriceText(g){return g.price==null?'—':g.price===0?'非卖品':g.price.toLocaleString('zh-CN')+'G'}
function characterGiftIds(c){return [...new Set([...(c.likedGifts||[]),...(c.preferredGifts||[])])]}
function giftPeople(g){return [...(g.likedBy||[]).map(id=>({id,stage:'最爱'})),...(g.preferredBy||[]).filter(id=>!(g.likedBy||[]).includes(id)).map(id=>({id,stage:'喜欢'}))]}
function giftLevel(c,g){return (c.likedGifts||[]).includes(g.id)?'最爱':'喜欢'}
function allGifts(){return CATALOG.gifts||[]}
function giftsPage(){
 const gifts=allGifts(),q=query.trim().toLowerCase();
 const catCounts=new Map();
 for(const g of gifts)catCounts.set(g.category,(catCounts.get(g.category)||0)+1);
 const topCats=['all',...[...catCounts.entries()].sort((a,b)=>b[1]-a[1]).map(([k])=>k)];
 const filteredGifts=gifts.filter(g=>{
  if(giftCategoryFilter!=='all'&&g.category!==giftCategoryFilter)return false;
  if(giftCharacterFilter&&!giftPeople(g).some(p=>p.id===giftCharacterFilter))return false;
  if(!q)return true;
  const lovers=giftPeople(g).map(({id})=>DB.characters.find(c=>c.id===id)?.cn||'').join(' ');
  return [g.name,g.nameEn||'',g.nameJa||'',...(g.aliases||[]),g.category,...(g.sources||[]),lovers].join(' ').toLowerCase().includes(q);
 });
 const giftById=new Map(gifts.map(g=>[g.id,g]));
 const filteredChars=DB.characters.filter(c=>{
  if(giftCharacterFilter&&c.id!==giftCharacterFilter)return false;
  if(giftCategoryFilter!=='all'&&!(c.giftCategories||[]).includes(giftCategoryFilter)&&!characterGiftIds(c).some(id=>giftById.get(id)?.category===giftCategoryFilter))return false;
  if(!q)return true;
  const likedNames=characterGiftIds(c).map(id=>giftById.get(id)?.name||'').join(' ');
  return [c.cn,c.name,c.alias||'',c.birthday||'',...(c.giftCategories||[]),likedNames].join(' ').toLowerCase().includes(q);
 });
 const viewKey='gifts-page',mode=arenaViewState[viewKey]||giftViewMode;
 const tab=(v,n,c)=>`<button id="gifts-view-tab-${v}" role="tab" data-view-tab="${v}" aria-selected="${mode===v}" aria-controls="gifts-view-panel-${v}" tabindex="${mode===v?0:-1}" class="${mode===v?'active':''}">${n} <span class="tab-count">${c}</span></button>`;
 const giftRowsHtml=`<div class="equipment-library equipment-ledger gift-ledger"><div class="equipment-ledger-head gift-ledger-head" aria-hidden="true"><span>礼物与分类</span><span>价格</span><span>获取方式与地点</span><span>喜爱它的角色</span></div>${filteredGifts.map(g=>`<article class="equipment-row gift-row" id="gift-${escapeAttr(g.id)}"><div class="equipment-row-name" data-skill-images="off"><div><h3>${esc(g.name)}</h3><small><button type="button" class="text-button gift-cat-pill" data-gift-cat="${escapeAttr(g.category)}">${esc(g.category)}</button>${g.nameEn?` · ${esc(g.nameEn)}`:''}</small></div></div><div class="gift-price-cell"><b>${giftPriceText(g)}</b></div><div class="equipment-row-info" data-skill-images="off"><p class="equipment-row-effect">${(g.sources||[]).length?esc(g.sources.join(' · ')):'—'}</p>${(g.places||[]).length?`<div class="gift-places">${g.places.slice(0,3).map(pl=>`<button type="button" class="text-button" data-goto-map="${escapeAttr(pl)}">${esc(pl)} ↗</button>`).join('')}</div>`:''}</div>${peopleStack(giftPeople(g),{max:6,label:g.name,empty:'—'})}</article>`).join('')||'<p class="muted" style="padding:18px">没有匹配的礼物。</p>'}</div>`;
 const giftLinks=items=>items.map(g=>`<button type="button" class="text-button gift-inline-link" data-reference-type="gift" data-reference-id="${escapeAttr(g.id)}" aria-label="查看${escapeAttr(g.name)}礼物资料">${esc(g.name)}</button>`).join('')||'<span class="muted">—</span>';
 const charRowsHtml=`<div class="table-wrap dense-table-wrap gift-character-wrap" tabindex="0" aria-label="角色赠礼表，可横向滚动"><table class="dense-table gift-character-table"><thead><tr><th scope="col">角色 / 生日</th><th scope="col">最爱</th><th scope="col">喜欢</th></tr></thead><tbody>${filteredChars.map(c=>{const liked=characterGiftIds(c).map(id=>giftById.get(id)).filter(g=>g&&(giftCategoryFilter==='all'||g.category===giftCategoryFilter));return `<tr><th scope="row">${tableCharacter(c,{subtitle:c.birthday||'生日未记录',showRating:false})}${c.giftCategories?.length?`<div class="gift-character-categories" aria-label="偏好分类">${c.giftCategories.map(cat=>`<button type="button" class="text-button gift-cat-chip" data-gift-cat="${escapeAttr(cat)}">${esc(cat)}</button>`).join('')}</div>`:''}</th><td>${giftLinks(liked.filter(g=>giftLevel(c,g)==='最爱'))}</td><td>${giftLinks(liked.filter(g=>giftLevel(c,g)==='喜欢'))}</td></tr>`}).join('')||'<tr><td colspan="3">没有匹配角色，请调整筛选。</td></tr>'}</tbody></table></div>`;
 return title('全局好感与挖角资料','礼物与角色喜好','')
  +filterDeck(toolbar('搜索礼物、分类、角色、生日或获取商店…',searchCount(mode==='gifts'?filteredGifts.length:filteredChars.length,mode==='gifts'?gifts.length:DB.characters.length,mode==='gifts'?'件礼物':'名角色')),[
   ['筛选',`<label class="gift-category-select">分类 <select data-gift-category aria-label="礼物分类">${topCats.map(cat=>`<option value="${escapeAttr(cat)}" ${giftCategoryFilter===cat?'selected':''}>${cat==='all'?'全部分类':esc(cat)}（${cat==='all'?gifts.length:catCounts.get(cat)}）</option>`).join('')}</select></label>${characterPicker({kind:'gift',value:giftCharacterFilter,characters:DB.characters,trigger:'全部角色',clearLabel:'全部角色',aria:'按喜爱角色筛选礼物'})}${giftCategoryFilter!=='all'||giftCharacterFilter?`<button type="button" class="text-button" data-gift-reset>重置筛选 ↺</button>`:''}`,'fdeck-selects']
  ])
  +`<div class="view-switcher equipment-views gift-views" data-view-group="${viewKey}" data-view-kind="arena"><div class="view-tabs" role="tablist" aria-label="礼物数据库查看维度">${tab('gifts','按礼物找角色',filteredGifts.length+' 件')}${tab('characters','按角色找礼物',filteredChars.length+' 人')}</div><section role="tabpanel" data-view-panel="gifts" id="gifts-view-panel-gifts" aria-labelledby="gifts-view-tab-gifts" ${mode==='gifts'?'':'hidden'}>${giftRowsHtml}</section><section role="tabpanel" data-view-panel="characters" id="gifts-view-panel-characters" aria-labelledby="gifts-view-tab-characters" ${mode==='characters'?'':'hidden'}>${charRowsHtml}</section></div>`;
}
document.addEventListener('click',e=>{
 const gcf=e.target.closest?.('[data-char-gifts]');
 if(gcf){e.preventDefault();giftCharacterFilter=gcf.dataset.charGifts;giftCategoryFilter='all';arenaViewState['gifts-page']='characters';location.hash='#characters/gifts';render();return}
 const gc=e.target.closest?.('[data-gift-cat]');
 if(gc){giftCategoryFilter=gc.dataset.giftCat===giftCategoryFilter&&gc.dataset.giftCat!=='all'?'all':gc.dataset.giftCat;if(guidePage()!=='gifts'&&!(guidePage()==='characters'&&rosterView==='gifts'))location.hash='#characters/gifts';render();return}
 if(e.target.closest?.('[data-gift-reset]')){giftCategoryFilter='all';giftCharacterFilter='';query='';render();return}
 const gj=e.target.closest?.('[data-gift-jump]');
 if(gj){
  if(typeof closeClassQuick==='function')closeClassQuick();
  const id=gj.dataset.giftJump,g=allGifts().find(x=>x.id===id);
  arenaViewState['gifts-page']='gifts';giftCategoryFilter='all';giftCharacterFilter='';
  if(g)query=g.name;
  if(guidePage()!=='gifts'&&!(guidePage()==='characters'&&rosterView==='gifts'))location.hash='#characters/gifts';else render();
  return;
 }
});

// 角色对比：最多四人并排，比较成长率、起始面板、技能、终局方向与推荐装备；选择保存在地址与本机存储里便于恢复与分享。
const COMPARE_MAX=4,COMPARE_STORE='fw-compare-ids-v1';
let compareIds=[];
try{const saved=JSON.parse(localStorage.getItem(COMPARE_STORE)||'[]');if(Array.isArray(saved))compareIds=saved.filter(x=>typeof x==='string'&&/^c\d+$/.test(x)).slice(0,COMPARE_MAX)}catch{}
function saveCompareIds(ids){try{localStorage.setItem(COMPARE_STORE,JSON.stringify(ids))}catch{}}
function loadCompareIds(){try{const saved=JSON.parse(localStorage.getItem(COMPARE_STORE)||'[]');return Array.isArray(saved)?saved.filter(id=>DB.characters.some(c=>c.id===id)).slice(0,COMPARE_MAX):[]}catch{return []}}
function compareHash(ids){return '#characters/compare'+(ids.length?'/'+ids.join(','):'')}
function compareFromHash(){
 const parts=location.hash.slice(1).split('/'),list=parts[0]==='characters'?parts[2]:parts[1];
 if(list!==undefined){
  const ids=[...new Set(list.split(',').filter(id=>DB.characters.some(c=>c.id===id)))].slice(0,COMPARE_MAX);
  compareIds=ids;saveCompareIds(ids);return ids;
 }
 const cached=loadCompareIds();
 compareIds=cached;
 if(cached.length&&(guidePage()==='compare'||rosterView==='compare')&&window.history?.replaceState)history.replaceState(null,'',compareHash(cached));
 return compareIds;
}
function setCompare(ids){compareIds=ids.slice(0,COMPARE_MAX);saveCompareIds(compareIds);location.hash=compareHash(compareIds);render()}
function compareCell(values,v,fmt=x=>x){const nums=values.filter(x=>Number.isFinite(x)),top=nums.length>1&&v===Math.max(...nums)&&nums.some(x=>x!==v);return `<td class="${top?'compare-top':''}">${Number.isFinite(v)?fmt(v):'<span class="muted">—</span>'}</td>`}
function comparePage(){const ids=compareFromHash(),cs=ids.map(id=>DB.characters.find(c=>c.id===id)),keys=Object.keys(statNames),num=v=>v===''||v==null?NaN:Number(v),growthTotal=c=>keys.reduce((s,k)=>s+num(c.growth[k]||0),0),skills=v=>(v||'').split(':').filter(Boolean).map(skillName).join('、')||'—';
 const picker=`<div class="compare-picker">${cs.map(c=>`<span class="compare-chip">${portrait(c)}<b>${esc(c.cn)}</b><button type="button" data-compare-remove="${c.id}" aria-label="移出对比：${esc(c.cn)}"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button></span>`).join('')}${cs.length<COMPARE_MAX?characterPicker({kind:'compare',characters:DB.characters.filter(c=>!ids.includes(c.id)),trigger:`＋ 添加角色（${cs.length}/${COMPARE_MAX}）`,aria:'添加对比角色',variant:'add',groups:RATING_TIERS.map(t=>({label:'评级 '+t,items:DB.characters.filter(c=>c.rating===t&&!ids.includes(c.id))}))}):''}${cs.length?'<button type="button" class="text-button" data-compare-clear>清空</button>':''}</div>`;
 if(cs.length<2)return title('全局角色资料','角色对比','')+picker+`<div class="compare-empty"><p>${cs.length?'再选一名角色即可开始对比。':'从上方选择两到四名角色开始对比，也可以在角色详情页点「加入对比」。'}</p><div class="compare-suggest">${[['c8','c7'],['c7','c0','c2','c5']].filter(set=>set.every(id=>DB.characters.some(c=>c.id===id))).map(set=>`<a class="button-link" href="${compareHash(set)}">${set.map(id=>esc(DB.characters.find(c=>c.id===id).cn)).join(' × ')}</a>`).join('')}</div></div>`;
 const head=`<tr><th scope="col"><span class="visually-hidden">项目</span></th>${cs.map(c=>`<th scope="col"><button type="button" class="compare-person" data-char="${c.id}">${portrait(c)}<span><b>${esc(c.cn)}</b><small>${esc(c.role)}</small></span></button></th>`).join('')}</tr>`,group=(name)=>`<tr class="compare-group"><th colspan="${cs.length+1}" scope="colgroup">${name}</th></tr>`,row=(label,cells)=>`<tr><th scope="row">${label}</th>${cells}</tr>`,text=f=>cs.map(c=>`<td>${f(c)}</td>`).join('');
 const growthRows=keys.map(k=>{const vals=cs.map(c=>num(c.growth[k]));return row(esc(statNames[k]),cs.map((c,i)=>{const v=vals[i];return compareCell(vals,v,x=>`<span class="compare-growth" style="--growth-color:${growthColor(x)}">${x}%</span>`)}).join(''))}).join('')+row('合计',(()=>{const vals=cs.map(growthTotal);return cs.map((c,i)=>compareCell(vals,vals[i],x=>`<b>${x}%</b>`)).join('')})());
 const baseRows=row('等级 / 初始职业',text(c=>c.baseLevel?`Lv.${c.baseLevel} · ${esc(className(c.startClass)||c.startClass||'')}`:'<span class="muted">待核实</span>'))+keys.map(k=>{const vals=cs.map(c=>c.baseStats?num(c.baseStats[k]):NaN);return row(esc(statNames[k]),cs.map((c,i)=>compareCell(vals,vals[i])).join(''))}).join('');
 return title('全局角色资料','角色对比','')+picker+`<div class="table-wrap compare-wrap"><table class="compare-table" style="--compare-cols:${cs.length}"><thead>${head}</thead><tbody>${group('概况')}${row('综合评级',text(c=>ratingBadge(c,true)))}${row('终局方向',text(c=>esc(finalBuild(c).end)))}${row('擅长 / 不擅长',text(c=>`<span>${esc(skills(c.good))}</span><small class="muted">不擅长 ${esc(skills(c.bad))}</small>`))}${row('评级理由',text(c=>`<small>${esc(c.ratingReason||'')}</small>`))}${group('个人技能')}${row('技能',text(c=>`<b>${esc(c.personalSkill||'—')}</b><small>${esc(c.personalSkillEffect||'')}</small>`))}${group('基础成长率')}${growthRows}${group('参考起始面板')}${baseRows}${group('推荐装备')}${row('装备',text(c=>(c.gearIds||[]).map(id=>EQUIPMENT.find(e=>e.id===id)).filter(Boolean).map(e=>`<button type="button" class="text-button" data-reference-type="equipment" data-reference-id="${e.id}">${esc(e.name)}</button>`).join('<br>')||'—'))}</tbody></table></div>`}
document.addEventListener('click',e=>{const rm=e.target.closest?.('[data-compare-remove]');if(rm){setCompare(compareIds.filter(id=>id!==rm.dataset.compareRemove));return}if(e.target.closest?.('[data-compare-clear]')){setCompare([]);return}const link=e.target.closest?.('a[href^="#compare/"]');if(link){const raw=link.getAttribute('href').slice(9).split(',').filter(id=>DB.characters.some(c=>c.id===id)).slice(0,COMPARE_MAX);if(raw.length){compareIds=raw;saveCompareIds(raw)}}});

// Keep rating rationale ahead of skills, and give the skills section its own table-of-contents entry.
function enhanceCharacterDetailHierarchy(){
 const page=document.getElementById?.('characterPage'),body=page?.querySelector('.character-page-body');if(!body)return;
 const skills=body.querySelector(':scope > .skill-growth'),rating=body.querySelector(':scope > .rating-analysis');
 if(skills&&rating&&(skills.compareDocumentPosition(rating)&Node.DOCUMENT_POSITION_FOLLOWING))skills.before(rating);
 const toc=page.querySelector('.character-toc ol'),skillHeading=skills?.querySelector('h2[id]');
 if(toc&&skillHeading&&!toc.querySelector(`[data-scroll="${skillHeading.id}"]`)){const ratingItem=[...toc.children].find(item=>item.textContent.includes('评级理由'));if(ratingItem){const item=document.createElement('li'),button=document.createElement('button');button.type='button';button.dataset.scroll=skillHeading.id;button.textContent='角色技能';item.appendChild(button);ratingItem.after(item)}}
}
const updateCharacterTocBase=updateCharacterToc;
updateCharacterToc=function(){enhanceCharacterDetailHierarchy();return updateCharacterTocBase()};

function closeCharacterFilterMenus(except=null,focus=false){for(const root of document.querySelectorAll('[data-character-filter]')){if(root===except)continue;const panel=root.querySelector('.character-filter-popover'),toggle=root.querySelector('[data-character-filter-toggle]');if(panel)panel.hidden=true;toggle?.setAttribute('aria-expanded','false')}if(focus)except?.querySelector('[data-character-filter-toggle]')?.focus()}
document.addEventListener('click',e=>{const toggle=e.target.closest?.('[data-character-filter-toggle]');if(toggle){const root=toggle.closest('[data-character-filter]'),panel=root.querySelector('.character-filter-popover'),open=panel.hidden;closeCharacterFilterMenus(root);panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));if(open)panel.querySelector('[data-character-filter-search]')?.focus();return}const pick=e.target.closest?.('[data-character-filter-pick]');if(pick){const kind=pick.dataset.characterFilterPick,value=pick.dataset.characterFilterValue||'';if(kind==='compare'){if(value)setCompare([...compareIds,value]);return}if(kind==='gift'){giftCharacterFilter=value;render();requestAnimationFrame(()=>document.querySelector('[data-character-filter-toggle="gift"]')?.focus());return}if(kind==='equipment')equipmentFor=value;else classFor=value;render();requestAnimationFrame(()=>document.querySelector(`[data-character-filter-toggle="${kind}"]`)?.focus());return}if(!e.target.closest?.('[data-character-filter]'))closeCharacterFilterMenus()});
document.addEventListener('input',e=>{const input=e.target.closest?.('[data-character-filter-search]');if(!input)return;const root=input.closest('[data-character-filter]'),q=input.value.trim().toLowerCase();let count=0;for(const option of root.querySelectorAll('[data-character-filter-value]')){const all=!option.dataset.characterFilterValue,match=!all&&option.dataset.characterFilterText.includes(q);option.hidden=all?Boolean(q):!match;if(match)count++}for(const group of root.querySelectorAll('.character-filter-group'))group.hidden=!group.querySelector('[data-character-filter-value]:not([hidden])');const empty=root.querySelector('.character-filter-empty');if(empty)empty.hidden=count>0});
document.addEventListener('keydown',e=>{const root=e.target.closest?.('[data-character-filter]');if(!root)return;if(e.key==='Escape'){e.preventDefault();closeCharacterFilterMenus(null,false);root.querySelector('[data-character-filter-toggle]')?.focus();return}if(!['ArrowDown','ArrowUp'].includes(e.key))return;const options=[...root.querySelectorAll('[data-character-filter-pick]:not([hidden])')],i=options.indexOf(document.activeElement),next=i<0?(e.key==='ArrowDown'?0:options.length-1):(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;e.preventDefault();options[next]?.focus()});

document.addEventListener('change',e=>{if(e.target.matches?.('[data-gift-category]')){giftCategoryFilter=e.target.value;render();document.querySelector('[data-gift-category]')?.focus()}});

document.addEventListener('click',e=>{const b=e.target.closest?.('[data-material-equipment]');if(!b)return;query=b.dataset.materialEquipment;equipmentType='all';equipmentFor='';location.hash='#equipment';render()});
// Explicit directory navigation starts a fresh search; character card/list switches share it.
function catalogueSearchScope(hash){const parts=hash.replace(/^#/,'').split('/');return parts[0]==='characters'&&parts[1]==='gifts'?'gifts':parts[0]}
document.addEventListener('click',e=>{const a=e.target.closest?.('#pageNav a,.roster-views a');if(!a)return;const next=a.getAttribute('href');if(!next?.startsWith('#'))return;if(catalogueSearchScope(next)!==catalogueSearchScope(location.hash))query='';},true);
